"""Tests of the new specification. Every test runs and each failure is reported.
Passing them all does not mean the project is correct."""
from api import clock_text, flight_problem, parse_clock, parse_flight, windows_overlap


def same(a, b):
    """Equal values of the same type (True is not 1, a tuple is not a list); floats within a small tolerance."""
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return abs(a - b) <= 1e-9 * max(1.0, abs(a), abs(b))
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return type(a) is type(b) and len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    return type(a) is type(b) and a == b


def short(x):
    r = repr(x)
    return r if len(r) <= 200 else r[:200] + "..."


TESTS = [
    ('parse_clock', parse_clock, ('17:56',), (17, 56)),
    ('parse_clock', parse_clock, ('04:16',), (4, 16)),
    ('clock_text', clock_text, (1440,), {'next_day': True, 'time': '00:00'}),
    ('clock_text', clock_text, (2442,), {'next_day': True, 'time': '16:42'}),
    ('windows_overlap', windows_overlap, ({'start': 214, 'end': 300}, {'start': 100, 'end': 200}, 15), True),
    ('windows_overlap', windows_overlap, ({'start': 100, 'end': 200}, {'start': 199, 'end': 300}, 0), True),
    ('parse_flight', parse_flight, ('EZ15 AT76 09:04-09:13 I',), {'aircraft': 'AT76', 'arrive': 544, 'code': 'EZ15', 'depart': 553, 'intl': True, 'size': 'C'}),
    ('parse_flight', parse_flight, ('  IB77 B738 23:50-00:40 D ',), {'aircraft': 'B738', 'arrive': 1430, 'code': 'IB77', 'depart': 1480, 'intl': False, 'size': 'C'}),
    ('flight_problem', flight_problem, ({'code': 'LH3', 'aircraft': 'MD11', 'size': None, 'arrive': 400, 'depart': 490, 'intl': True},), 'unknown aircraft'),
    ('flight_problem', flight_problem, ({'code': 'EZ10', 'aircraft': 'B738', 'size': 'C', 'arrive': 643, 'depart': 668, 'intl': False},), 'turn too short'),
]


def main():
    n = len(TESTS)
    failed = 0
    for k, (name, func, args, want) in enumerate(TESTS):
        shown = name + "(" + ", ".join(short(a) for a in args) + ")"
        if func is None:
            failed += 1
            print(f"FAIL test {k + 1}: {name} is not defined (api.py could not import it)")
            continue
        try:
            got = func(*args)
        except Exception as e:
            failed += 1
            print(f"FAIL test {k + 1}: {shown} raised {type(e).__name__}: {e}; expected {short(want)}")
            continue
        if not same(got, want):
            failed += 1
            print(f"FAIL test {k + 1}: {shown}: expected {short(want)}, got {short(got)}")
    print(f"{n - failed}/{n} tests passed")
    if failed:
        raise SystemExit(1)


main()

