"""Fish species profiles: what each species eats, how much, and how fast it grows. Lengths in mm, food in mg."""
FOODS = ['algae', 'flakes', 'frozen', 'pellets']
FRESHWATER = {'neon': ('flakes', 3, 1, 30), 'guppy': ('flakes', 4, 2, 50)}
CICHLIDS = {'angelfish': ('pellets', 8, 3, 150)}
MARINE = {'clownfish': ('pellets', 6, 2, 110), 'tang': ('algae', 12, 4, 250)}
PREDATORS = {'lionfish': ('frozen', 20, 4, 380)}
BOTTOM = {'pleco': ('algae', 10, 5, 300)}
FAST_DAYS = {'algae': [], 'flakes': [6], 'frozen': [2, 6], 'pellets': [6]}

def species_profile(species):
    """The profile of a species.

    Returns a dict {"food": str, "rate": int, "growth": int, "max_length": int}: the food it eats, its RATE in mg
    of food per 10 mm of fish per day, its GROWTH in mm per week while juvenile, and its adult size in mm:
    neon flakes 3, 1, 30; guppy flakes 4, 2, 50; angelfish pellets 8, 3, 150; clownfish pellets 6, 2, 110;
    tang algae 12, 4, 250; lionfish frozen 20, 4, 380; pleco algae 10, 5, 300.

    Valid inputs: species is one of neon, guppy, angelfish, clownfish, tang, lionfish, pleco.
    """
    table = {**FRESHWATER, **CICHLIDS, **MARINE, **PREDATORS, **BOTTOM}
    food, rate, growth, max_length = table[species]
    return {'food': food, 'rate': rate, 'growth': growth, 'max_length': max_length}

def is_juvenile(profile, length):
    """Is a fish with this species profile and `length` mm still a juvenile?

    It is while it is shorter than half the adult size: length * 2 < profile["max_length"].

    Returns a bool.

    Valid inputs: profile is a dict as species_profile returns; length is an int from 1 to its max_length.
    """
    return length * 2 < profile['max_length']

def fish_ration(profile, length, weekday):
    """The food one fish with this species profile gets on a day, in milligrams.

    The base ration is length * profile["rate"] // 10. A juvenile (is_juvenile) gets the base ration * 3 // 2 and
    never fasts. An adult fasts (gets 0) on the FAST_DAYS of its food: flakes and pellets eaters on weekday 6
    (Sunday), frozen-food eaters on weekdays 2 and 6 (Wednesday and Sunday), algae eaters never. Weekdays count 0
    for Monday to 6 for Sunday.

    Returns an int.

    Valid inputs: as is_juvenile; weekday is an int from 0 to 6.
    """
    base = length * profile['rate'] // 10
    if is_juvenile(profile, length):
        return base * 3 // 2
    if weekday in FAST_DAYS[profile['food']]:
        return 0
    return base

