"""Tests of the new specification. Every test runs and each failure is reported.
Passing them all does not mean the project is correct."""
from api import altitude_degrees, angular_separation, parse_position, parse_timestamp, sidereal_degrees, to_degrees


def same(a, b):
    """Equal values of the same type (True is not 1, a tuple is not a list); floats within a small tolerance."""
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return abs(a - b) <= 1e-9 * max(1.0, abs(a), abs(b))
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return type(a) is type(b) and len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    return type(a) is type(b) and a == b


def short(x):
    r = repr(x)
    return r if len(r) <= 200 else r[:200] + "..."


TESTS = [
    ('parse_position', parse_position, ('08h27m13s', '-53d20m13s'), {'dec': -192013, 'ra': 30433}),
    ('parse_position', parse_position, ('01h26m28s', '-81d32m50s'), {'dec': -293570, 'ra': 5188}),
    ('to_degrees', to_degrees, ({'ra': 43200, 'dec': 324000},), (180.0, 90.0)),
    ('to_degrees', to_degrees, ({'ra': 58997, 'dec': -268947},), (245.82083333333333, -74.7075)),
    ('angular_separation', angular_separation, ({'ra': 76424, 'dec': -240118}, {'ra': 84485, 'dec': -68381}), 52.374),
    ('angular_separation', angular_separation, ({'ra': 83967, 'dec': -45552}, {'ra': 22283, 'dec': -85918}), 96.421),
    ('parse_timestamp', parse_timestamp, ('2030-12-31 23:59',), 16305119),
    ('parse_timestamp', parse_timestamp, ('2012-12-09 00:22',), 6805462),
    ('sidereal_degrees', sidereal_degrees, (12508051, 0.0), 74.1952),
    ('sidereal_degrees', sidereal_degrees, (6556329, 0.0), 269.8764),
    ('altitude_degrees', altitude_degrees, (20117, -19408, 4391283, (64.13, -21.9)), 7.9),
    ('altitude_degrees', altitude_degrees, (45599, -41843, 11041451, (34.05, -118.25)), 35.1),
]


def main():
    n = len(TESTS)
    failed = 0
    for k, (name, func, args, want) in enumerate(TESTS):
        shown = name + "(" + ", ".join(short(a) for a in args) + ")"
        if func is None:
            failed += 1
            print(f"FAIL test {k + 1}: {name} is not defined (api.py could not import it)")
            continue
        try:
            got = func(*args)
        except Exception as e:
            failed += 1
            print(f"FAIL test {k + 1}: {shown} raised {type(e).__name__}: {e}; expected {short(want)}")
            continue
        if not same(got, want):
            failed += 1
            print(f"FAIL test {k + 1}: {shown}: expected {short(want)}, got {short(got)}")
    print(f"{n - failed}/{n} tests passed")
    if failed:
        raise SystemExit(1)


main()

