"""Times when a group of members is free and the room is not taken."""
from availability import merge_windows

def intersect_windows(a, b):
    """The times that are in both lists of windows: for each window of a and each window of b on the same day, the
    part from the later start to the earlier end, kept when it is longer than 0 minutes.

    Returns a list of windows, merged as availability.merge_windows does.

    Valid inputs: a and b are lists of 0 to 30 windows, each list sorted with no overlaps.
    """
    out = []
    for day, start, end in a:
        for other_day, other_start, other_end in b:
            if day != other_day:
                continue
            lo = max(start, other_start)
            hi = min(end, other_end)
            if hi > lo:
                out.append((day, lo, hi))
    return merge_windows(out)

def subtract_busy(windows, busy):
    """The parts of the windows that no busy window covers.

    Each busy window on the same day cuts its time out of a window, which can split it in two. Pieces of 0 minutes
    are dropped. A busy window may overlap other busy windows.

    Returns a list of windows, sorted by (day, start).

    Valid inputs: windows is a list of 0 to 30 windows, sorted with no overlaps; busy is a list of 0 to 30 windows.
    """
    pieces = list(windows)
    for b_day, b_start, b_end in busy:
        cut = []
        for day, start, end in pieces:
            if day != b_day or b_end <= start or b_start >= end:
                cut.append((day, start, end))
                continue
            if b_start > start:
                cut.append((day, start, b_start))
            if b_end < end:
                cut.append((day, b_end, end))
        pieces = cut
    return sorted(pieces)

def common_free_time(table, members, busy):
    """When every one of `members` is free and the room is not busy.

    The windows of the first member (table.get, [] when the member is not in the table) are intersected with those
    of each other member in turn (intersect_windows); then subtract_busy takes out the busy windows.

    Returns a list of windows, sorted by (day, start).

    Valid inputs: table is a dict as availability.availability_table returns; members is a list of 1 to 6 names;
    busy is a list of 0 to 30 windows.
    """
    free = table.get(members[0], [])
    for name in members[1:]:
        free = intersect_windows(free, table.get(name, []))
    return subtract_busy(free, busy)

