"""Warnings raised by a single inspection."""
from colony_health import WASH_BEES, mite_band, mite_rate

def inspection_issues(rec):
    """The warnings for one inspection, in this order (each at most once):

    "brood above bees" when brood > bees;
    "no queen" when queen is "N" and brood is 0;
    "check queen" when queen is "N" and brood > 0;
    "mites high" when the mite band (colony_health) is "high";
    "mites rising" when the mite band is "moderate";
    "defensive" when temper >= 3;
    "weak" when bees < 3.

    Returns a list of str, empty when nothing is wrong.

    Valid inputs: rec is a dict as field_notes.parse_inspection returns.
    """
    issues = []
    if rec['brood'] > rec['bees']:
        issues.append('brood above bees')
    if rec['queen'] == 'N':
        issues.append('no queen' if rec['brood'] == 0 else 'check queen')
    band = mite_band(rec)
    if band == 'high':
        issues.append('mites high')
    elif band == 'moderate':
        issues.append('mites rising')
    if rec['temper'] >= 3:
        issues.append('defensive')
    if rec['bees'] < 3:
        issues.append('weak')
    return issues

