"""Per-point counts: the highest count of each species over the visits of one season."""
from tally import parse_visit

def point_counts(lines, year):
    """The count of each species at each point surveyed in `year`.

    Each line is read with tally.parse_visit; lines of other years are ignored. Within one visit, the counts of
    all items with the same code are added (heard-only items count too). The point's count of a species is the
    largest such visit total over all visits to that point in that year. Codes "UNID" are left out. A point that
    was visited but has no species still appears, with an empty dict.

    Returns a dict {point: {code: count}}.

    Valid inputs: lines is a list of 0 to 20 strs as tally.parse_visit accepts; year is an int.
    """
    result = {}
    for line in lines:
        visit = parse_visit(line)
        if visit['year'] != year:
            continue
        totals = {}
        for code, count, heard in visit['items']:
            if code == 'UNID':
                continue
            totals[code] = totals.get(code, 0) + count
        best = result.setdefault(visit['point'], {})
        for code, total in totals.items():
            if total > best.get(code, 0):
                best[code] = total
    return result

