"""Splitting rolls into the ten frames of a game, and checking a split game."""

def split_frames(rolls):
    """Group the rolls of a game (possibly unfinished) into frames.

    Frames 1 to 9: a first roll of 10 is a strike and fills the frame alone; otherwise the frame is two rolls (the
    last frame can be left with one roll when the rolls run out). Frame 10 takes all the rolls that are left. Only
    frames that have at least one roll are listed.

    Returns a list of at most 10 dicts, one per frame in order: {"number": int (1 to 10), "rolls": list of the
    frame's ints, "first": int (the index in `rolls` of the frame's first roll)}.

    Valid inputs: rolls is a list of 0 to 25 ints from 0 to 10.
    """
    out = []
    i = 0
    while i < len(rolls) and len(out) < 9:
        if rolls[i] == 10:
            out.append({'number': len(out) + 1, 'rolls': [10], 'first': i})
            i += 1
        else:
            out.append({'number': len(out) + 1, 'rolls': rolls[i:i + 2], 'first': i})
            i += 2
    if i < len(rolls):
        out.append({'number': len(out) + 1, 'rolls': rolls[i:], 'first': i})
    return out

def game_problem(frames):
    """Why a game, given as its frames, is not a legal (possibly unfinished) game, or None when it is.

    `frames` is the game already split into frames: the list split_frames returns for its rolls (the rolls are the
    "rolls" of the frames, in order).

    The checks, in this order, the first failing one giving the answer:
    "bad roll" when a roll is below 0 or above 10;
    "frame N over 10" for the first of frames 1-9 (N is the frame's "number") whose two rolls add up to more than
    10;
    "tenth frame" when frame 10 is illegal: its first two rolls add up to more than 10 while the first is not a
    strike; or after a strike the second and third add up to more than 10 while the second is not a strike; or it
    has a third roll although the first two neither include a strike nor add up to 10; or it has more than three
    rolls.

    Returns a str or None.

    Valid inputs: frames is split_frames(rolls) for a list rolls of 0 to 25 ints from -1 to 11.
    """
    for frame in frames:
        for pins in frame['rolls']:
            if pins < 0 or pins > 10:
                return 'bad roll'
    for frame in frames[:9]:
        if sum(frame['rolls']) > 10:
            return f"frame {frame['number']} over 10"
    if len(frames) < 10:
        return None
    last = frames[9]['rolls']
    if len(last) > 3:
        return 'tenth frame'
    if len(last) >= 2 and last[0] < 10 and (last[0] + last[1] > 10):
        return 'tenth frame'
    if len(last) == 3 and last[0] == 10 and (last[1] < 10) and (last[1] + last[2] > 10):
        return 'tenth frame'
    if len(last) == 3 and last[0] < 10 and (last[0] + last[1] < 10):
        return 'tenth frame'
    return None

