"""Reading candle recipes, and the wax data they refer to."""
MELT_C = {'soy': 49, 'paraffin': 58, 'beeswax': 63, 'coconut': 38, 'palm': 60}
DENSITY = {'soy': 900, 'paraffin': 880, 'beeswax': 960, 'coconut': 920, 'palm': 890}
MAX_LOAD = {'soy': 120, 'paraffin': 100, 'beeswax': 60, 'coconut': 120, 'palm': 90}
PRICE = {'soy': 1100, 'paraffin': 650, 'beeswax': 2400, 'coconut': 1800, 'palm': 1300}
PRICE.update({'fragrance': 9000, 'dye': 15000})

def parse_tenths(text):
    """A percentage written with at most one decimal ("8", "8.5", "0.3"), as a whole number of tenths of a percent.

    Spaces around the text are ignored. "8" gives 80, "8.5" gives 85, "0.3" gives 3, "12." gives 120.

    Returns an int.

    Valid inputs: text is digits, optionally followed by "." and zero or one digit, with at least one digit before
    the "."; spaces may surround it.
    """
    whole, _, frac = text.strip().partition('.')
    tenths = int(whole) * 10
    if frac:
        tenths += int(frac)
    return tenths

def parse_recipe(text):
    """Parse a recipe "waxes | fragrance | dye", where the "| dye" part may be left out (dye 0).

    waxes is a "," separated list of "name parts" items (name and parts separated by spaces); names are
    lower-cased, and parts of the same name are added together. fragrance and dye are percentages of the wax weight
    as parse_tenths reads them.

    Returns a dict {"waxes": list of (name, parts) tuples sorted by name, "fragrance": tenths of a percent (int),
    "dye": tenths of a percent (int)}.

    Valid inputs: text has one or two "|"; waxes has 1 to 6 items, each a name of letters and a decimal int 0-100;
    fragrance and dye are as parse_tenths accepts.
    """
    fields = text.split('|')
    totals = {}
    for item in fields[0].split(','):
        name, parts = item.split()
        totals[name.lower()] = totals.get(name.lower(), 0) + int(parts)
    dye = parse_tenths(fields[2]) if len(fields) > 2 else 0
    return {'waxes': sorted(totals.items()), 'fragrance': parse_tenths(fields[1]), 'dye': dye}

