"""Quantities written as a number and a unit, such as "42.5km", converted to whole base units."""
import re
DISTANCE_SCALE = {'m': 1, 'km': 1000, 'mi': 1609}
ENERGY_SCALE = {'Wh': 1, 'kWh': 1000, 'MWh': 1000000}
MASS_SCALE = {'g': 1, 'kg': 1000, 'lb': 454}
KINDS = [('distance', DISTANCE_SCALE), ('energy', ENERGY_SCALE), ('mass', MASS_SCALE)]

def split_quantity(text):
    """Split a quantity into its number part and its unit part.

    Spaces around `text` are ignored. The number part is the longest prefix of the stripped text made only of the
    characters "0"-"9" and "."; the unit part is the rest, stripped of spaces.

    Returns a tuple (number text, unit text); either can be "".

    Valid inputs: text is a str of 0 to 20 ASCII characters.
    """
    text = text.strip()
    cut = len(text)
    for i, ch in enumerate(text):
        if not ('0' <= ch <= '9' or ch == '.'):
            cut = i
            break
    return (text[:cut], text[cut:].strip())

def unit_scale(unit):
    """The kind and size of a unit, in base units (metres, watt-hours, grams).

    Units (case-sensitive): distance "m" 1, "km" 1000, "mi" 1609; energy "Wh" 1, "kWh" 1000, "MWh" 1000000;
    mass "g" 1, "kg" 1000, "lb" 454.

    Returns a tuple (kind, base units per unit) with kind "distance", "energy" or "mass", or None for any other unit.

    Valid inputs: unit is a str.
    """
    for kind, table in KINDS:
        if unit in table:
            return (kind, table[unit])
    return None

def is_quantity(text):
    """Is `text` a quantity that to_base_units accepts?

    True when, after split_quantity, the number part is one or more digits optionally followed by "." and one or two
    digits, and the unit part is a unit known to unit_scale.

    Returns a bool.

    Valid inputs: text is a str of 0 to 20 ASCII characters.
    """
    number, unit = split_quantity(text)
    if re.fullmatch('[0-9]+(\\.[0-9]{1,2})?', number) is None:
        return False
    return unit_scale(unit) is not None

def hundredths(number):
    """A decimal number with at most two decimals, as a whole number of hundredths ("42.5" -> 4250, "7" -> 700).

    Returns an int.

    Valid inputs: number is one or more digits, optionally followed by "." and one or two digits.
    """
    whole, _, frac = number.partition('.')
    frac = (frac + '00')[:2]
    return int(whole) * 100 + int(frac)

def to_base_units(text):
    """A quantity converted to whole base units of its kind.

    The amount is hundredths(number) * scale / 100 rounded to the nearest whole base unit, halves rounded up.

    Returns a tuple (amount, kind): an int >= 0 and the unit's kind as unit_scale gives it.

    Valid inputs: text is a str for which is_quantity is True.
    """
    number, unit = split_quantity(text)
    kind, scale = unit_scale(unit)
    amount = (hundredths(number) * scale + 50) // 100
    return (amount, kind)

