"""Ranking five-card poker hands given as parsed cards."""
LOW_NAMES = ['high card', 'pair', 'two pair', 'three of a kind', 'straight']
NAMES = LOW_NAMES + ['flush', 'full house', 'four of a kind', 'straight flush']

def straight_high(values):
    """The top card of a straight, or 0 when the values are not a straight.

    values is a list of five rank values. They are a straight when all five differ and the largest minus the smallest
    is 4 (top card = the largest), or when they are exactly {14, 2, 3, 4, 5} (the ace counts low; top card = 5).

    Returns an int (0, or 5 to 14).

    Valid inputs: values is a list of five ints from 2 to 14.
    """
    distinct = sorted(set(values))
    if len(distinct) != 5:
        return 0
    if distinct == [2, 3, 4, 5, 14]:
        return 5
    if distinct[4] - distinct[0] == 4:
        return distinct[4]
    return 0

def hand_rank(cards):
    """Rank a five-card hand so that a larger (category, tiebreak) pair is a better hand.

    Category: 8 straight flush, 7 four of a kind, 6 full house, 5 flush (all one suit), 4 straight, 3 three of a kind,
    2 two pair, 1 pair, 0 high card; its name is NAMES[category] ("high card", "pair", ..., "straight flush").
    Tie-break list: for a straight or straight flush, [top card from straight_high]; otherwise the distinct rank
    values ordered by how often they occur (most first) and then by value (highest first), e.g. full house
    K K K 2 2 -> [13, 2], two pair 9 9 4 4 A -> [9, 4, 14].

    Returns a dict {"category": int, "name": str, "tiebreak": list of ints}. Two hands compare by the tuple
    (category, tiebreak) with Python comparison.

    Valid inputs: cards is a list of five distinct cards, each a (rank value, suit) tuple as cards.parse_card returns
    (rank value 2 to 14, suit one of "C", "D", "H", "S").
    """
    values = [v for v, _ in cards]
    flush = len({s for _, s in cards}) == 1
    top = straight_high(values)
    if top:
        category = 8 if flush else 4
        return {'category': category, 'name': NAMES[category], 'tiebreak': [top]}
    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    order = sorted(counts, key=lambda v: (-counts[v], -v))
    shape = sorted(counts.values(), reverse=True)
    if shape[0] == 4:
        category = 7
    elif shape == [3, 2]:
        category = 6
    elif flush:
        category = 5
    elif shape[0] == 3:
        category = 3
    elif shape == [2, 2, 1]:
        category = 2
    elif shape[0] == 2:
        category = 1
    else:
        category = 0
    return {'category': category, 'name': NAMES[category], 'tiebreak': order}

