"""Melds: sets (three or four cards of one rank) and runs (three or more cards in sequence in one suit)."""
from cards import parse_card, sort_cards

def is_set(cards):
    """Are `cards` a set: three or four cards of the same rank, no two of the same suit?

    Returns a bool.

    Valid inputs: cards is a list of 0 to 11 distinct cards (cards.is_card True for each).
    """
    if len(cards) < 3 or len(cards) > 4:
        return False
    ranks = [parse_card(card)[0] for card in cards]
    suits = [parse_card(card)[1] for card in cards]
    if any((rank != ranks[0] for rank in ranks)):
        return False
    return len(set(suits)) == len(suits)

def is_run(cards):
    """Are `cards` a run: three or more cards of one suit whose ranks, sorted, are consecutive?

    The ace is low only: A-2-3 is a run, Q-K-A is not. The cards may be given in any order.

    Returns a bool.

    Valid inputs: as is_set.
    """
    if len(cards) < 3:
        return False
    parsed = sorted(((parse_card(card)['rank'], parse_card(card)['suit']) for card in cards))
    low, suit = parsed[0]
    for i, (rank, other) in enumerate(parsed):
        if other != suit or rank != low + i:
            return False
    return True

def candidate_melds(cards):
    """Every set and run that can be made from `cards`.

    First the sets, by rank (ace first): for a rank held three times, the set of those three; for a rank held four
    times, the set of all four and then the four sets of three, leaving out the C, D, H, S card in turn. Then the
    runs, by suit in the order C, D, H, S, then by lowest rank, then shortest first. Each meld lists its cards in
    cards.sort_cards order.

    Returns a list of tuples of strs.

    Valid inputs: as is_set.
    """
    hand = sort_cards(cards)
    out = []
    for rank in range(1, 14):
        group = [card for card in hand if parse_card(card)['rank'] == rank]
        if len(group) >= 3:
            out.append(tuple(group))
        if len(group) == 4:
            for i in range(4):
                out.append(tuple(group[:i] + group[i + 1:]))
    for suit in 'CDHS':
        same = [card for card in hand if parse_card(card)['suit'] == suit]
        for i in range(len(same)):
            for j in range(i + 3, len(same) + 1):
                if is_run(same[i:j]):
                    out.append(tuple(same[i:j]))
    return out

