"""Each cat's status in the shelter, as a state machine driven by the log's events."""
from dates import days_between
from events import age_months, event_order
QUARANTINE_DAYS = 10
RETURN_DAYS = 30
ALLOWED = {'intake': ['none', 'gone'], 'clear': ['quarantine'], 'foster': ['available']}
ALLOWED.update({'unfoster': ['foster'], 'adopt': ['available', 'foster'], 'return': ['adopted']})
ALLOWED['transfer'] = ['quarantine', 'available']
NEXT_STATE = {'intake': 'quarantine', 'clear': 'available', 'foster': 'foster', 'unfoster': 'available'}
NEXT_STATE.update({'adopt': 'adopted', 'return': 'quarantine', 'transfer': 'gone'})

def new_record():
    """The record of a cat the shelter has not seen yet.

    Returns the dict {"state": "none", "since": "", "intake": "", "age": 0, "color": "", "adopter": "",
    "adoptions": 0}.

    Valid inputs: none (no arguments).
    """
    return {'state': 'none', 'since': '', 'intake': '', 'age': 0, 'color': '', 'adopter': '', 'adoptions': 0}

def step(record, event):
    """Apply one event to a cat's record.

    The checks, in this order, the first failing one rejecting the event (the record stays as it was):
    "unknown action" when the action is not one of intake, clear, foster, unfoster, adopt, return, transfer;
    "not allowed" when the record's state is not one the action starts from (intake: none or gone; clear:
    quarantine; foster: available; unfoster: foster; adopt: available or foster; return: adopted; transfer:
    quarantine or available); "too early" for clear when fewer than QUARANTINE_DAYS (10) days have passed since
    "since"; "no adopter" for adopt without a "to" extra; "late return" for return more than RETURN_DAYS (30) days
    after "since".
    An accepted event sets "state" to the action's new state (intake and return: quarantine; clear and unfoster:
    available; foster: foster; adopt: adopted; transfer: gone) and "since" to the event's date. Also: intake sets
    "intake" to the date, "age" to events.age_months of the "age" extra (12 when missing) and "color" to the "color"
    extra ("unknown" when missing); adopt sets "adopter" to the "to" extra and adds 1 to "adoptions"; return sets
    "adopter" to "".

    Returns a tuple (record, reason): the new record (a new dict; the given one is not changed) and None, or the
    unchanged record and the reason.

    Valid inputs: record is a dict as new_record returns or step produced; event is an event as
    events.parse_event returns, dated on or after record["since"].
    """
    day, action, extras = (event['date'], event['action'], event['extras'])
    if action not in ALLOWED:
        return (record, 'unknown action')
    if record['state'] not in ALLOWED[action]:
        return (record, 'not allowed')
    if action == 'clear' and days_between(record['since'], day) < QUARANTINE_DAYS:
        return (record, 'too early')
    if action == 'adopt' and 'to' not in extras:
        return (record, 'no adopter')
    if action == 'return' and days_between(record['since'], day) > RETURN_DAYS:
        return (record, 'late return')
    out = dict(record)
    out['state'] = NEXT_STATE[action]
    out['since'] = day
    if action == 'intake':
        out['intake'] = day
        out['age'] = age_months(extras['age']) if 'age' in extras else 12
        out['color'] = extras.get('color', 'unknown')
    elif action == 'adopt':
        out['adopter'] = extras['to']
        out['adoptions'] += 1
    elif action == 'return':
        out['adopter'] = ''
    return (out, None)

def replay(lines):
    """Run every event of the log through step, in events.event_order, each cat starting from new_record.

    Returns a dict {"cats": {cat: final record}, keys inserted in name order, one per cat named in the log;
    "rejected": list of (line number, reason) tuples in processing order}.

    Valid inputs: lines as events.event_order accepts.
    """
    cats = {}
    rejected = []
    for event in event_order(lines):
        cat = event['cat']
        record, reason = step(cats.get(cat, new_record()), event)
        cats[cat] = record
        if reason is not None:
            rejected.append((event['line'], reason))
    return {'cats': {name: cats[name] for name in sorted(cats)}, 'rejected': rejected}

