"""Data sessions "YYYY-MM-DD home|roam amount", added up per billing month."""
from amounts import parse_data

def parse_session(line):
    """Read a session line such as "2024-05-03 roam 120MB" (words separated by one or more spaces).

    Returns a tuple (month "YYYY-MM", kind "home" or "roam", amount in KB from amounts.parse_data).

    Valid inputs: line is a date "YYYY-MM-DD", the kind ("home" or "roam") and an amount as amounts.parse_data
    accepts.
    """
    day, kind, amount = line.split()
    return (day[:7], kind, parse_data(amount))

def month_usage(lines):
    """The home and roaming data of every billing month from the first to the last month with a session.

    Months between them without a session are listed with (0, 0).

    Returns a dict {"YYYY-MM": (home KB, roam KB)}, keys inserted in month order; {} when lines is empty.

    Valid inputs: lines is a list of 0 to 30 strs as parse_session accepts.
    """
    totals = {}
    for line in lines:
        month, kind, kb = parse_session(line)
        home, roam = totals.get(month, (0, 0))
        totals[month] = (home + kb, roam) if kind == 'home' else (home, roam + kb)
    if not totals:
        return {}
    first, last = (min(totals), max(totals))
    year, month = (int(first[:4]), int(first[5:]))
    out = {}
    for _ in range(12 * (int(last[:4]) - year + 1)):
        key = f'{year:04d}-{month:02d}'
        out[key] = totals.get(key, (0, 0))
        if key == last:
            break
        month += 1
        if month == 13:
            year, month = (year + 1, 1)
    return out

