"""Counting the atoms in a chemical formula."""
import re
TOKEN = re.compile('[A-Z][a-z]?|[0-9]+|[()]')

def formula_tokens(text):
    """Split a formula (with no "*") into tokens.

    A token is an element symbol (an upper-case letter, optionally followed by one lower-case letter), a run of
    digits, "(" or ")". Tokens come in the order they appear.

    Returns a list of str, for example "Ca(OH)2" gives ["Ca", "(", "O", "H", ")", "2"].

    Valid inputs: text is a string of letters, digits and parentheses as described.
    """
    return TOKEN.findall(text)

def group_counts(text):
    """The atom counts of a formula without "*" and without a leading number, such as "Al2(SO4)3".

    A count after a symbol multiplies that symbol, and a count after ")" multiplies the whole group since the
    matching "("; with no count the factor is 1. Groups can be nested.

    Returns a dict {symbol: count} with every symbol that appears (counts above 0).

    Valid inputs: text is a non-empty formula of symbols, counts from 1 to 99 and balanced parentheses, where every
    count follows a symbol or ")".
    """
    stack = [{}]
    pending = None
    for token in formula_tokens(text):
        if token.isdigit():
            for symbol, n in pending.items():
                stack[-1][symbol] = stack[-1].get(symbol, 0) + n * int(token)
            pending = None
            continue
        if pending is not None:
            for symbol, n in pending.items():
                stack[-1][symbol] = stack[-1].get(symbol, 0) + n
        if token == '(':
            stack.append({})
            pending = None
        elif token == ')':
            pending = stack.pop()
        else:
            pending = {token: 1}
    if pending is not None:
        for symbol, n in pending.items():
            stack[-1][symbol] = stack[-1].get(symbol, 0) + n
    return stack[0]

def atom_counts(formula):
    """The number of atoms of each element in one unit of `formula`.

    The formula may consist of parts joined by "*" (a hydrate such as "CuSO4*5H2O"). Each part may start with a
    number that multiplies the whole part ("5H2O" is 5 times H2O); the rest of the part is read as group_counts
    reads it. The counts of all parts are added.

    Returns a list of (symbol, count) tuples, one per element that appears, sorted by symbol in string order, for
    example "CuSO4*5H2O" gives [("Cu", 1), ("H", 10), ("O", 9), ("S", 1)].

    Valid inputs: formula is a string of 1 to 30 characters made of such parts, every part's rest as group_counts
    accepts.
    """
    total = {}
    for part in formula.split('*'):
        digits = 0
        for ch in part:
            if not ch.isdigit():
                break
            digits += 1
        times = int(part[:digits]) if digits else 1
        for symbol, n in group_counts(part[digits:]).items():
            total[symbol] = total.get(symbol, 0) + n * times
    return sorted(total.items())

