        return sorted(slide_squares(board, f, r, BISHOP_DIRS, white))
    if kind == 'Q':
        return sorted(slide_squares(board, f, r, ROOK_DIRS + BISHOP_DIRS, white))
    steps = KNIGHT_STEPS if kind == 'N' else KING_STEPS
    out = []
    for df, dr in steps:
        sq = shift_square(here, df, dr)
        if sq is not None:
            other = board.get(square_name(sq))
            if other is None or other.isupper() != white:
                out.append(square_name(sq))
    return sorted(out)

def in_check(board, white):
    """Is the king of colour `white` attacked?

    The king (letter "K" for white, "k" for black) is attacked when its square is among the piece_targets of some
    piece of the other colour (a pawn's diagonal captures count; its forward moves never reach an occupied square).

    Returns a bool.

    Valid inputs: board as piece_targets accepts, holding exactly one king of each colour.
    """
    king = 'K' if white else 'k'
    home = None
    for sq in sorted(board):
        if board[sq] == king:
            home = sq
    for sq in sorted(board):
        if board[sq].isupper() != white and home in piece_targets(board, sq):
            return True
    return False

