files.stress.py:
"""Level of traffic stress (LTS) of street segments: 1 is calm enough for children, 4 only for confident riders.

Both functions take a whole segment: a dict with at least the keys "length" (int meters), "lane" (str) and "speed"
(int km/h), such as segments.parse_segment returns.
"""
STRESS_FACTOR = {1: 10, 2: 13, 3: 20, 4: 40}

def segment_stress(segment):
    """The level of traffic stress of riding a segment, from its "lane" and its "speed" limit.

    Rules, with speed in km/h:
    - "protected": 1 at any speed;
    - "painted": 2 when speed <= 40, else 3;
    - "shared": 1 when speed <= 20, 2 when speed <= 30, 3 when speed <= 50, else 4;
    - "none": 2 when speed <= 20, 3 when speed <= 40, else 4.

    Returns an int from 1 to 4.

    Valid inputs: segment is a dict whose "lane" is one of "protected", "painted", "shared", "none" and whose "speed"
    is an int from 10 to 120 (other keys are ignored).
    """
    lane, speed = (segment['lane'], segment['speed'])
    if lane == 'protected':
        return 1
    if lane == 'painted':
        return 2 if speed <= 40 else 3
    if lane == 'shared':
        limits = [(20, 1), (30, 2), (50, 3)]
    else:
        limits = [(20, 2), (40, 3)]
    for top, level in limits:
        if speed <= top:
            return level
    return 4

def segment_cost(segment):
    """The effective length of a segment for route choice: stressful streets count as longer.

    With level = segment_stress(segment), the cost is segment["length"] * STRESS_FACTOR[level] / 10, rounded half
    up to an int; STRESS_FACTOR is {1: 10, 2: 13, 3: 20, 4: 40}.

    Returns an int.

    Valid inputs: segment is a dict as segment_stress accepts, with "length" an int from 1 to 99999.
    """
    level = segment_stress(segment)
    return (segment['length'] * STRESS_FACTOR[level] + 5) // 10

