"""Giving every student a seat, one student at a time."""
from order import placement_order
from room import adjacent_seats, desk_seats, is_aisle_seat, label_position, seat_label
FRONT_ROWS = 2

def seat_allowed(layout, seat, student, taken, conflicts):
    """May `student` take `seat`, given the seats already taken?

    The seat must be free (not a key of taken). When the student needs "front", its row must be below FRONT_ROWS
    (2), i.e. row 0 or 1. When the student needs "aisle", it must be an aisle seat: the cell just left or just right
    of it in the same row exists and is open floor ("."). And no seat next to it (the desks directly in front,
    behind, left and right of it; a neighbor cell counts only when it exists in its row and is "D") may be taken by a
    student in the student's conflict list.

    Returns a bool.

    Valid inputs: layout as room.desk_seats accepts; seat is a (row, column) seat of layout; student is a dict as
    roster.parse_student returns; taken is a dict {(row, column): name}; conflicts is a dict as
    roster.parse_conflicts returns.
    """
    if seat in taken:
        return False
    row, col = seat
    if 'front' in student['needs'] and row >= FRONT_ROWS:
        return False
    label = seat_label(row, col)
    if 'aisle' in student['needs'] and (not is_aisle_seat(layout, label)):
        return False
    avoid = conflicts.get(student['name'], [])
    for near in adjacent_seats(layout, label):
        if taken.get(label_position(near)) in avoid:
            return False
    return True

def assign_seats(students, conflicts, layout):
    """Seat the students one by one in order.placement_order.

    Each student takes the first seat in room.desk_seats order (front to back, left to right) that seat_allowed
    accepts, given the students seated before. A student with no allowed seat stays unseated.

    Returns a dict {"seats": {name: (row, column)} for every seated student, "unseated": list of names in placement
    order}.

    Valid inputs: students as order.placement_order accepts; conflicts and layout as seat_allowed accepts.
    """
    by_name = {s['name']: s for s in students}
    taken = {}
    seats = {}
    unseated = []
    for name in placement_order(students):
        for seat in map(label_position, desk_seats(layout)):
            if seat_allowed(layout, seat, by_name[name], taken, conflicts):
                taken[seat] = name
                seats[name] = seat
                break
        else:
            unseated.append(name)
    return {'seats': seats, 'unseated': unseated}

