"""Climbing grades in three systems, placed on one difficulty scale of steps.

Rope routes are graded in the Yosemite Decimal System ("yds": "5.5" to "5.9", then "5.10a" to "5.15d") or the French
sport scale ("french": "4c" to "9c", some grades with a "+"). A rope grade's step is 1 for 5.5 up to 5 for 5.9; from
5.10 on, 5.Na to 5.Nd are the steps 6 + 4 * (N - 10) + 0, 1, 2, 3, so 5.10a is 6 and 5.15d is 29. Boulders are graded
on the V scale ("v": "VB", then "V0" to "V17"), whose step is the V number, and -1 for VB.
"""
LETTERS = 'abcd'
FRENCH_NAMES = ['4c', '5a', '5b', '5c', '6a', '6a+', '6b', '6b+', '6c', '6c+', '7a', '7a+', '7b', '7b+']
FRENCH_NAMES += ['7c', '7c+', '8a', '8a+', '8b', '8b+', '8c', '8c+', '9a', '9a+', '9b', '9b+', '9c']
FRENCH_STEPS = [2, 3, 4, 5, 6, 7, 8, 9, 10] + list(range(12, 30))

def parse_grade(text):
    """The system and step of a grade written as text.

    The text is stripped of spaces first and letters may be in any case. A grade starting with "V" is a boulder
    grade ("VB" or "V" and a number). A grade starting with "5." is YDS. Anything else is French, whose steps are
    those of the table FRENCH_NAMES / FRENCH_STEPS: 4c 2, 5a 3, 5b 4, 5c 5, 6a 6, 6a+ 7, 6b 8, 6b+ 9, 6c 10, 6c+ 12,
    and from 7a (13) on each next grade one step more, up to 9c (29).

    Returns a grade record: a dict {"system": "yds", "french" or "v", "step": int}.

    Valid inputs: text is a grade of one of the three systems as described in this module, possibly with spaces
    around it and in any case.
    """
    g = text.strip().lower()
    if g.startswith('v'):
        if g == 'vb':
            return {'system': 'v', 'step': -1}
        return {'system': 'v', 'step': int(g[1:])}
    if g.startswith('5.'):
        rest = g[2:]
        if len(rest) == 1:
            return {'system': 'yds', 'step': int(rest) - 4}
        number = int(rest[:-1])
        return {'system': 'yds', 'step': 6 + 4 * (number - 10) + LETTERS.index(rest[-1])}
    return {'system': 'french', 'step': FRENCH_STEPS[FRENCH_NAMES.index(g)]}

def grade_name(grade):
    """The name of a grade record in its own system: the inverse of parse_grade, written in lower case except "V".

    With system = grade["system"] and step = grade["step"]: for "yds" it is the grade whose step is `step` (e.g.
    "5.9", "5.11c"). For "french" it is the French grade with the largest step that is not above `step` (so step 11
    gives "6c"), or "4c" when step is below 2. For "v" it is "VB" for -1, else "V" followed by the number.

    Returns a str.

    Valid inputs: grade is a dict {"system": "yds", "french" or "v", "step": int}, with step an int from 1 to 29 for
    "yds" and "french", from -1 to 17 for "v" (other keys are ignored).
    """
    system, step = (grade['system'], grade['step'])
    if system == 'v':
        return 'VB' if step < 0 else 'V' + str(step)
    if system == 'yds':
        if step <= 5:
            return '5.' + str(step + 4)
        number, letter = divmod(step - 6, 4)
        return '5.' + str(10 + number) + LETTERS[letter]
    best = FRENCH_NAMES[0]
    for name, value in zip(FRENCH_NAMES, FRENCH_STEPS):
        if value <= step:
            best = name
    return best

