"""Change with the fewest coins, from an unlimited or a limited supply."""

def change_rank(counts):
    """The sort key that orders ways of making change: fewer coins first, then more of the largest coin, then
    more of the next largest, and so on.

    Returns a tuple: (sum of counts, then each count negated, in the order given).

    Valid inputs: counts is a list of ints from 0 to 2000, one per coin value, largest coin first.
    """
    return tuple([sum(counts)] + [-n for n in counts])

def fewest_table(limit, coins):
    """The fewest coins needed for each amount from 0 to `limit` that can be made, with an unlimited supply of
    each coin.

    Returns a dict {amount: smallest number of coins that add up to exactly that many cents}; an amount that cannot
    be made is not a key. 0 is always a key, with value 0.

    Valid inputs: limit is an int from 0 to 400; coins is a list of 1 to 8 distinct ints from 1 to 10000.
    """
    table = [0] + [None] * limit
    for a in range(1, limit + 1):
        for coin in coins:
            if coin <= a and table[a - coin] is not None:
                if table[a] is None or table[a - coin] + 1 < table[a]:
                    table[a] = table[a - coin] + 1
    return {a: n for a, n in enumerate(table) if n is not None}

def optimal_change(amount, coins):
    """The best way to make `amount` cents with an unlimited supply of each coin.

    Best means the smallest change_rank: fewest coins; among those, the most of the largest coin; then the most
    of the next largest; and so on.

    Returns a list of (coin value, count) tuples holding only the coins used (count >= 1), largest coin first, or
    None when amount cannot be made exactly. An amount of 0 gives [].

    Valid inputs: amount is an int from 0 to 400; coins is a list of 1 to 8 distinct ints from 1 to 10000.
    """
    order = sorted(coins, reverse=True)
    best = [[0] * len(order)] + [None] * amount
    for a in range(1, amount + 1):
        for k, coin in enumerate(order):
            if coin <= a and best[a - coin] is not None:
                trial = list(best[a - coin])
                trial[k] += 1
                if best[a] is None or change_rank(trial) < change_rank(best[a]):
                    best[a] = trial
    if best[amount] is None:
        return None
    return [(coin, n) for coin, n in zip(order, best[amount]) if n > 0]

def bounded_change(amount, supply):
    """The best way to make `amount` cents from a limited supply of coins.

    supply lists (coin value, count) stock entries: at most count coins of that value may be used. Best is as in
    optimal_change (smallest change_rank). Coins with a count of 0 cannot be used.

    Returns a list of (coin value, count) tuples holding only the coins used (count >= 1), largest coin first, or
    None when amount cannot be made exactly from the supply. An amount of 0 gives [].

    Valid inputs: amount is an int from 0 to 300; supply is a list of 1 to 8 (coin value, count) tuples of ints,
    in any order, with distinct coin values from 1 to 10000 and counts from 0 to 200.
    """
    stock = dict(supply)
    order = sorted(stock, reverse=True)
    best = [[]] + [None] * amount
    for coin in order:
        layer = [None] * (amount + 1)
        for a in range(amount + 1):
            for n in range(min(stock[coin], a // coin) + 1):
                rest = best[a - n * coin]
                if rest is None:
                    continue
                trial = rest + [n]
                if layer[a] is None or change_rank(trial) < change_rank(layer[a]):
                    layer[a] = trial
        best = layer
    if best[amount] is None:
        return None
    return [(coin, n) for coin, n in zip(order, best[amount]) if n > 0]

