"""Facts about a whole collection: series held, duplicate copies and value."""
from listing import parse_collection
from runs import compress_runs, longest_run
from value import copy_value

def numbers_by_title(text):
    """The issue numbers held of each title.

    Returns a dict {title: sorted list of distinct issue numbers} over listing.parse_collection(text).

    Valid inputs: text is valid for listing.parse_collection.
    """
    held = {}
    for issue in parse_collection(text):
        held.setdefault(issue['title'], set()).add(issue['number'])
    return {title: sorted(nums) for title, nums in held.items()}

def series_stats(text):
    """For each title: how many distinct issues, in how many runs (runs.compress_runs), and the length of the
    longest run (runs.longest_run; last - first + 1).

    Returns a dict {title: (issues, runs, longest) tuple of ints}.

    Valid inputs: as numbers_by_title.
    """
    stats = {}
    for title, numbers in numbers_by_title(text).items():
        best = longest_run(numbers)
        stats[title] = (len(numbers), len(compress_runs(numbers)), best[1] - best[0] + 1)
    return stats

def duplicate_copies(text):
    """The spare copies: for each title and number held more than once, every copy but the best one.

    The best copy has the highest grade, then the lowest paid price, then comes first in the listing.

    Returns a list of (title, number, grade) tuples, sorted by title, then number, then grade from high to low.

    Valid inputs: as numbers_by_title.
    """
    copies = {}
    for pos, issue in enumerate(parse_collection(text)):
        key = (issue['title'], issue['number'])
        copies.setdefault(key, []).append((-issue['grade'], issue['paid'], pos))
    spares = []
    for (title, number), ranked in copies.items():
        for neg_grade, paid, pos in sorted(ranked)[1:]:
            spares.append((title, number, -neg_grade))
    spares.sort(key=lambda s: (s[0], s[1], -s[2]))
    return spares

def collection_value(text, guide):
    """The value of the whole collection against what was paid.

    Returns a dict {"value": sum of value.copy_value over the copies in the guide, "paid": sum of all paid prices,
    "gain": value - paid of the copies in the guide only, "unpriced": number of copies not in the guide} (cents).

    Valid inputs: text as numbers_by_title accepts; guide as value.copy_value accepts.
    """
    totals = {'value': 0, 'paid': 0, 'gain': 0, 'unpriced': 0}
    for issue in parse_collection(text):
        worth = copy_value(issue, guide)
        totals['paid'] += issue['paid']
        if worth is None:
            totals['unpriced'] += 1
        else:
            totals['value'] += worth
            totals['gain'] += worth - issue['paid']
    return totals

