"""Walking distances on the site: from plots to water taps, and which plots touch."""
from site_map import find_plots
WALKABLE = '.~'
STEPS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def tap_distance(grid, plot_id):
    """The fewest steps from a plot to a water tap.

    A step moves from a cell to one of its four edge neighbours inside the grid, and may only enter path (".") or
    tap ("~") cells; the walk starts on any cell of the plot (0 steps) and ends on entering a tap cell.

    Returns an int (at least 1), or None when no tap can be reached.

    Valid inputs: grid as site_map.find_plots accepts; plot_id is the id of one of its plots.
    """
    plot = [p for p in find_plots(grid) if p['id'] == plot_id][0]
    frontier = list(plot['cells'])
    seen = set(frontier)
    for step in range(1, len(grid) * len(grid[0]) + 1):
        reached = []
        for r, c in frontier:
            for dr, dc in STEPS:
                nr, nc = (r + dr, c + dc)
                if not (0 <= nr < len(grid) and 0 <= nc < len(grid[0])) or (nr, nc) in seen:
                    continue
                if grid[nr][nc] == '~':
                    return step
                if grid[nr][nc] in WALKABLE:
                    seen.add((nr, nc))
                    reached.append((nr, nc))
        if not reached:
            return None
        frontier = reached
    return None

def plot_neighbours(grid, plot_id):
    """The other plots that share a cell edge with a plot.

    Returns a list of plot ids in string order.

    Valid inputs: as tap_distance.
    """
    touching = set()
    for r, c in find_plots(grid)[plot_id]['cells']:
        for dr, dc in STEPS:
            nr, nc = (r + dr, c + dc)
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc].isalpha():
                other = grid[nr][nc].upper()
                if other != plot_id:
                    touching.add(other)
    return sorted(touching)

