"""Tests of the new specification. Every test runs and each failure is reported.
Passing them all does not mean the project is correct."""
from api import find_plots, parse_map, plot_area, plot_neighbours, tap_distance


def same(a, b):
    """Equal values of the same type (True is not 1, a tuple is not a list); floats within a small tolerance."""
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return abs(a - b) <= 1e-9 * max(1.0, abs(a), abs(b))
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return type(a) is type(b) and len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    return type(a) is type(b) and a == b


def short(x):
    r = repr(x)
    return r if len(r) <= 200 else r[:200] + "..."


TESTS = [
    ('parse_map', parse_map, ('.~......#..\n..J..#.M...\n......#M...\naa##..~M.#.\nkk........#',), ['.~......#..', '..J..#.M...', '......#M...', 'aa##..~M.#.', 'kk........#']),
    ('parse_map', parse_map, ('.hhh...~..\n....j...~.\n...KKKK..G\nMM.KKKK..G\n.........G',), ['.hhh...~..', '....j...~.', '...KKKK..G', 'MM.KKKK..G', '.........G']),
    ('find_plots', find_plots, (['aaa', '...', 'BBB', '~..'],), [{'cells': [(0, 0), (0, 1), (0, 2)], 'id': 'A', 'raised': True}, {'cells': [(2, 0), (2, 1), (2, 2)], 'id': 'B', 'raised': False}]),
    ('find_plots', find_plots, (['~..#.##.h', '..BBB....', '##.......', '.......##', '....NNN.#', '.LLL.....', 'GLLL..###', 'GLLL.....', '....#..#~'],), [{'cells': [(1, 2), (1, 3), (1, 4)], 'id': 'B', 'raised': False}, {'cells': [(6, 0), (7, 0)], 'id': 'G', 'raised': False}, {'cells': [(0, 8)], 'id': 'H', 'raised': True}, {'cells': [(5, 1), (5, 2), (5, 3), (6, 1), (6, 2), (6, 3), (7, 1), (7, 2), (7, 3)], 'id': 'L', 'raised': False}, {'cells': [(4, 4), (4, 5), (4, 6)], 'id': 'N', 'raised': False}]),
    ('plot_area', plot_area, ({'id': 'C', 'cells': [(2, 2)], 'raised': False},), 25),
    ('plot_area', plot_area, ({'id': 'A', 'cells': [(0, 0), (0, 1), (0, 2)], 'raised': True},), 75),
    ('tap_distance', tap_distance, (['~..#.##.h', '..BBB....', '##.......', '.......##', '....NNN.#', '.LLL.....', 'GLLL..###', 'GLLL.....', '....#..#~'], 'N'), 7),
    ('tap_distance', tap_distance, (['......d.#...', '...#.#d.....', '..FFFFd....#', '......H.#...', 'PPPP.#...#..', '............', '.JJJ...~..#.', '............', '..........#.'], 'P'), 6),
    ('plot_neighbours', plot_neighbours, (['aaa', '...', 'BBB', '~..'], 'A'), []),
    ('plot_neighbours', plot_neighbours, (['......d.#...', '...#.#d.....', '..FFFFd....#', '......H.#...', 'PPPP.#...#..', '............', '.JJJ...~..#.', '............', '..........#.'], 'P'), []),
]


def main():
    n = len(TESTS)
    failed = 0
    for k, (name, func, args, want) in enumerate(TESTS):
        shown = name + "(" + ", ".join(short(a) for a in args) + ")"
        if func is None:
            failed += 1
            print(f"FAIL test {k + 1}: {name} is not defined (api.py could not import it)")
            continue
        try:
            got = func(*args)
        except Exception as e:
            failed += 1
            print(f"FAIL test {k + 1}: {shown} raised {type(e).__name__}: {e}; expected {short(want)}")
            continue
        if not same(got, want):
            failed += 1
            print(f"FAIL test {k + 1}: {shown}: expected {short(want)}, got {short(got)}")
    print(f"{n - failed}/{n} tests passed")
    if failed:
        raise SystemExit(1)


main()

