"""Double-booked rooms and speakers who cannot be in two places."""
from venues import walk_minutes

def in_time_order(a, b):
    """The two sessions as a pair, the one that starts first first; equal starts by title.

    Returns a tuple (first session dict, second session dict).

    Valid inputs: a and b are session dicts as sessions.parse_session returns.
    """
    if (b['start'], b['title']) < (a['start'], a['title']):
        return (b, a)
    return (a, b)

def room_clashes(sessions):
    """Pairs of sessions on the same day in the same room whose times overlap.

    Times are half-open [start, end): one session ending at 10:00 and another starting at 10:00 do not overlap.

    Returns a list of (day, room, first title, second title) tuples, each pair in in_time_order, and the list sorted.

    Valid inputs: sessions is a list of 0 to 25 session dicts with distinct titles.
    """
    out = []
    for i, a in enumerate(sessions):
        for b in sessions[i + 1:]:
            if a['day'] != b['day'] or a['room'] != b['room']:
                continue
            if a['start'] < b['end'] and b['start'] < a['end']:
                first, second = in_time_order(a, b)
                out.append((a['day'], a['room'], first['title'], second['title']))
    return sorted(out)

def speaker_clashes(sessions):
    """Speakers booked into two sessions on the same day without enough time between them.

    For each pair of sessions on one day that share a speaker, put in in_time_order: the gap is the second's start
    minus the first's end. It is a clash when the gap is less than venues.walk_minutes from the first room to the
    second (overlapping sessions have a negative gap, so they always clash; a gap equal to the walk is fine).

    Returns a list of (speaker, first title, second title) tuples, one per shared speaker per clashing pair, sorted.

    Valid inputs: as room_clashes.
    """
    out = []
    for i, a in enumerate(sessions):
        for b in sessions[i + 1:]:
            if a['day'] != b['day']:
                continue
            first, second = in_time_order(a, b)
            gap = second['start'] - first['end']
            if gap >= walk_minutes(first['room'], second['room']):
                continue
            for name in a['speakers']:
                if name in b['speakers']:
                    out.append((name, first['title'], second['title']))
    return sorted(out)

