"""Percent cover of the bottom from transect points, in tenths of a percent (an int: 333 means 33.3%)."""
from codes import GROUPS
GROUP_NAMES = ['abiotic', 'algae', 'coral', 'dead']

def tenths(count, total):
    """count / total in tenths of a percent, rounded half up: (2000 * count + total) // (2 * total).

    Returns an int, for example 333 for (1, 3) and 667 for (2, 3).

    Valid inputs: total is an int from 1 to 5000; count an int from 0 to total.
    """
    return (2000 * count + total) // (2 * total)

def code_cover(points):
    """The percent cover of every code that occurs in points: its count over all points, with tenths.

    Returns a dict {code: tenths of a percent (int)} with only the codes that occur ({} for no points).

    Valid inputs: points is a list of 0 to 5000 codes of codes.GROUPS.
    """
    counts = {}
    for code in points:
        counts[code] = counts.get(code, 0) + 1
    return {code: tenths(count, len(points)) for code, count in counts.items()}

def group_cover(points):
    """The percent cover of each group of codes.GROUPS ("coral": HC, SC, BL; "algae": MA, TA; "dead": DC, RB;
    "abiotic": SD, RK), each from its own count of points with tenths (not from the rounded code covers).

    Returns a dict with the four keys of GROUP_NAMES, each in tenths of a percent (int); all 0 for no points.

    Valid inputs: as code_cover.
    """
    counts = {name: 0 for name in GROUP_NAMES}
    for code in points:
        counts[GROUPS[code]] += 1
    if not points:
        return {name: 0 for name in GROUP_NAMES}
    return {name: tenths(counts[name], len(points)) for name in GROUP_NAMES}

def bleaching_percent(points):
    """The share of hard coral that is bleached: BL points over HC plus BL points, as a whole percent rounded half
    up ((200 * BL + n) // (2 * n) with n = HC + BL); 0 when there is no HC or BL point.

    Returns an int.

    Valid inputs: as code_cover.
    """
    bleached = points.count('BL')
    hard = points.count('HC') + bleached
    if hard == 0:
        return 0
    return (200 * bleached + hard) // (2 * hard)

