"""A reef health score for one site and year."""
from cover import bleaching_percent, group_cover
from fish import biomass_grams, herbivore_share

def coral_points(coral):
    """Points for live coral cover (percent): 4 when at least 40, 3 when at least 25, 2 when at least 10, else 1.

    Returns an int.

    Valid inputs: coral is a float from 0 to 100.
    """
    if coral >= 40:
        return 4
    if coral >= 25:
        return 3
    if coral >= 10:
        return 2
    return 1

def site_score(points, entries):
    """The health score of a site from its pooled points and fish entries, never below 0.

    Start with coral_points of the "coral" group_cover. Algae: subtract 2 when the "algae" cover is greater than
    the coral cover, else subtract 1 when it is at least 20. Bleaching (bleaching_percent): subtract 2 when at
    least 30, else 1 when at least 10. Fish (biomass_grams / 1000 = kg): add 3 when at least 50 kg, else 2 when at
    least 20, else 1 when at least 5. Add 1 when herbivore_share is at least 40.

    Returns an int.

    Valid inputs: points is a non-empty list of codes as codes.parse_points returns; entries a list as
    fish.parse_fish returns.
    """
    cover = group_cover(points)
    score = coral_points(cover['coral'])
    if cover['algae'] > cover['coral']:
        score -= 2
    elif cover['algae'] >= 20:
        score -= 1
    bleached = bleaching_percent(points)
    if bleached >= 30:
        score -= 2
    elif bleached >= 10:
        score -= 1
    kilos = biomass_grams(entries) / 1000
    if kilos >= 50:
        score += 3
    elif kilos >= 20:
        score += 2
    elif kilos >= 5:
        score += 1
    if herbivore_share(entries) >= 40:
        score += 1
    return max(score, 0)

def health_class(score):
    """The class of a score: "poor" up to 2, "fair" 3-4, "good" 5-6, "excellent" from 7.

    Returns a str.

    Valid inputs: score is an int from 0 to 99.
    """
    if score >= 7:
        return 'excellent'
    if score >= 5:
        return 'good'
    if score >= 3:
        return 'fair'
    return 'poor'

