"""Batting figures: who faced which ball, runs, balls faced and strike rates."""
from deliveries import is_legal, is_wicket, parse_innings, runs_completed
from overs import BALLS_PER_OVER

def batting_card(text, order):
    """The batting figures of an innings.

    order lists the batters in batting order: order[0] starts on strike, order[1] at the other end. The deliveries
    (deliveries.parse_innings of text) are taken in order:
    - the striker's runs grow by the delivery's runs off the bat, and his balls faced by 1 for every delivery except
      a wide;
    - on a wicket the striker is out and the next batter in order who has not come in yet takes his place, on strike;
      when no batter is left the innings is over and the remaining deliveries are ignored;
    - on any other delivery the two batters change ends when deliveries.runs_completed is odd;
    - after each 6th legal delivery of an over (legal deliveries counted from the start, every 6th) they change ends
      again, on top of the change above.

    Returns a list of (name, runs, balls, out) tuples (out a bool) for every batter who came in, in batting order.

    Valid inputs: text is a str as deliveries.parse_innings accepts; order is a list of 2 to 11 distinct names.
    """
    rows = {order[0]: [0, 0, False], order[1]: [0, 0, False]}
    striker, other = (order[0], order[1])
    next_in = 2
    legal = 0
    for delivery in parse_innings(text):
        row = rows[striker]
        row[0] += delivery['bat']
        if delivery['kind'] != 'wide':
            row[1] += 1
        if delivery['legal']:
            legal += 1
        if delivery['out']:
            row[2] = True
            if next_in >= len(order):
