"""Reading ball-by-ball cricket deliveries written as short tokens."""
ILLEGAL_KINDS = ('wide', 'noball')

def make_delivery(kind, bat, extras):
    """Build the record of one delivery.

    Returns a tuple (kind, bat, extras): kind (str), runs off the bat (int), extras (int). Use is_legal and
    is_wicket to ask what kind of ball it was.

    Valid inputs: kind is one of "run", "wicket", "wide", "noball", "legbye", "bye"; bat and extras are ints 0-6.
    """
    return (kind, bat, extras)

def is_legal(delivery):
    """Does the delivery count as one of the six balls of an over?

    Returns a bool: False when its kind is "wide" or "noball", True otherwise.

    Valid inputs: delivery is a tuple as make_delivery builds.
    """
    return delivery[0] not in ILLEGAL_KINDS

def is_wicket(delivery):
    """Was the striker out on the delivery?

    Returns a bool: True only when its kind is "wicket".

    Valid inputs: delivery is a tuple as make_delivery builds.
    """
    return delivery[0] == 'wicket'

def parse_delivery(token):
    """Parse one delivery token into a record (make_delivery).

    Token forms:
    "0" to "6": that many runs off the bat, kind "run", 0 extras; "." is the same as "0";
    "W": the striker is out, kind "wicket", 0 runs off the bat, 0 extras;
    "<n>wd": a wide, kind "wide", 0 off the bat, n extras (n 1-5);
    "nb" or "nb<n>": a no-ball, kind "noball", n runs off the bat ("nb" means n = 0) and 1 extra;
    "<n>lb": leg byes, kind "legbye", 0 off the bat, n extras (n 1-4);
    "<n>b": byes, kind "bye", 0 off the bat, n extras (n 1-4).

    Returns a tuple (kind, bat, extras) as make_delivery builds.

    Valid inputs: token is a str in one of the forms above (for "nb<n>", n is 1-6).
    """
    if token == 'W':
        return make_delivery('wicket', 0, 0)
    if token == '.':
        return make_delivery('run', 0, 0)
    if token.startswith('nb'):
        bat = int(token[2:]) if len(token) > 2 else 0
        return make_delivery('noball', bat, 1)
    if token.endswith('wd'):
        return make_delivery('wide', 0, int(token[:-2]))
    if token.endswith('lb'):
        return make_delivery('legbye', 0, int(token[:-2]))
    if token.endswith('b'):
        return make_delivery('bye', 0, int(token[:-1]))
    return make_delivery('run', int(token), 0)

def parse_innings(text):
    """Parse an innings written as delivery tokens separated by whitespace.

    A token "|" only marks the end of an over for the reader and is skipped. Every other token is parsed with
    parse_delivery, keeping their order.

    Returns a list of (kind, bat, extras) tuples as make_delivery builds (empty for a text with no deliveries).

    Valid inputs: text is a str of 0 to 200 tokens separated by spaces, each "|" or a token parse_delivery accepts.
    """
    return [parse_delivery(token) for token in text.split() if token != '|']

def runs_completed(delivery):
    """The runs the two batters completed on a delivery (they change ends when it is odd).

    For kind "run" and "noball" it is the runs off the bat; for "legbye" and "bye" it is the extras; for "wide" it is
    the extras minus 1 (the one-run penalty is not run); for "wicket" it is 0.

    Returns an int.

    Valid inputs: delivery is a tuple as make_delivery builds.
    """
    kind, bat, extras = delivery
    if kind in ('run', 'noball'):
        return bat
    if kind == 'wide':
        return extras - 1
    if kind == 'wicket':
        return 0
    return extras

