"""Expanding one field of a cron expression ("1-5", "*/15", "0,30") into the values it allows."""

def expand_part(part, low, high):
    """The values allowed by one comma-free part of a cron field whose values run from low to high.

    Forms (a, b and s are decimal integers):
    - "*": every value from low to high;
    - "a": just a;
    - "a-b": every value from a to b, both included;
    - any of these followed by "/s": the values of the form start, start + s, start + 2s, ... that are at most
      the form's end, where start and end are low and high for "*", a and b for "a-b", and a and high for "a"
      (so "a/s" runs from a up to high).

    Returns a list of ints in increasing order.

    Valid inputs: part has one of those forms; low <= a <= b <= high; s is from 1 to high - low + 1; low and high
    are ints with 0 <= low < high <= 59.
    """
    step = 1
    stepped = '/' in part
    if stepped:
        part, step_text = part.split('/')
        step = int(step_text)
    if part == '*':
        start, stop = (low, high)
    elif '-' in part:
        first, last = part.split('-')
        start, stop = (int(first), int(last))
    else:
        start = int(part)
        stop = high if stepped else start
    return list(range(start, stop + 1, step))

def expand_field(text, low, high):
    """The values allowed by a whole cron field: the union of expand_part over its comma-separated parts.

    Returns a list of distinct ints in increasing order.

    Valid inputs: text is one or more parts joined by "," (no spaces), each valid for expand_part with this low
    and high.
    """
    values = []
    for part in text.split(','):
        for value in expand_part(part, low, high):
            if value not in values:
                values.append(value)
    values.sort()
    return values

