"""Comparing the letters in a grid with the answers."""
from entries import entry_cells, list_entries

def entry_pattern(grid, row, col, direction):
    """The letters of the entry starting at (row, col), with "?" for each empty square.

    Returns a str with one character per square of entries.entry_cells(grid, row, col, direction).

    Valid inputs: as entries.entry_cells.
    """
    text = ''
    for r, c in entry_cells(grid, (row, col), 'across' if direction == 'A' else 'down'):
        text += '?' if grid[r][c] == '.' else grid[r][c]
    return text

def check_answers(grid, answers):
    """Check every entry against an answer key.

    For each entry in entries.list_entries order, with pattern = entry_pattern of the entry:
    - "missing" if the label is not a key of answers;
    - else "length" if the answer's length differs from the entry's length;
    - else "wrong" if some lettered square differs from the answer's letter at that position (compared in upper case);
    - else "partial" if the pattern still has a "?";
    - else "ok".

    Returns a list of (label, status) tuples.

    Valid inputs: grid as layout.parse_layout returns; answers is a dict {label: word of ASCII letters}.
    """
    results = []
    for label, r, c, length in list_entries(grid):
        pattern = entry_pattern(grid, r, c, label[-1])
        if label not in answers:
            status = 'missing'
        elif len(answers[label]) != length:
            status = 'length'
        else:
            word = answers[label].upper()
            clash = any((p != '?' and p != w for p, w in zip(pattern, word)))
            status = 'wrong' if clash else 'partial' if '?' in pattern else 'ok'
        results.append((label, status))
    return results

def fill_ratio(grid):
    """The share of white squares that hold a letter.

    Returns a float: lettered squares / white squares, rounded to 3 decimals with round(); 0.0 when the grid has no
    white square.

    Valid inputs: grid as layout.parse_layout returns.
    """
    white = 0
    lettered = 0
    for row in grid:
        for ch in row:
            if ch != '#':
                white += 1
                if ch != '.':
                    lettered += 1
    if white == 0:
        return 0.0
    return round(lettered / white, 3)

