        pattern = entry_pattern(grid, entry['start'][0], entry['start'][1], label[-1])
        if label not in answers:
            status = 'missing'
        elif len(answers[label]) != length:
            status = 'length'
        else:
            word = answers[label].upper()
            clash = any((p != '?' and p != w for p, w in zip(pattern, word)))
            status = 'wrong' if clash else 'partial' if '?' in pattern else 'ok'
        results.append((label, status))
