"""Replaying the event log into each backer's current pledge."""
from events import days_before, parse_log
MIN_PLEDGE = 100
LOCK_DAYS = 2

def run_ledger(events, deadline):
    """Replay events (in the given order) and keep each backer's active pledge.

    Each event is either applied or ignored with a reason; the first rule that matches decides:
    - any event dated after the deadline: ignored, "after deadline";
    - "pledge": ignored with "already pledged" when the backer has an active pledge, with "below minimum" when the
      amount is below MIN_PLEDGE (100 cents); otherwise the backer gets an active pledge of that amount and the
      next queue number (0, 1, 2, ... over all applied pledges, so a backer who cancelled and pledged again moves
      to the back of the queue);
    - "raise": "no pledge" when the backer has no active pledge; otherwise the amount grows;
    - "lower": "no pledge" as for raise; "locked" when the event is fewer than LOCK_DAYS (2) days before the deadline
      (events.days_before); "below minimum" when the new amount would be below MIN_PLEDGE; otherwise it shrinks;
    - "cancel": "no pledge" and "locked" as for lower; otherwise the active pledge is removed.

    Returns a tuple (pledges, problems): pledges a dict {backer: [cents, queue number]} of active pledges; problems
    a list of (date, backer, reason) tuples for the ignored events, in event order.

    Valid inputs: events is a list as events.parse_log returns; deadline is a "YYYY-MM-DD" str.
    """
    pledges = {}
    problems = []
    queue = 0
    for event in events:
        day, action, backer = (event['date'], event['action'], event['backer'])
        cents = event['amount']
        before = days_before(day, deadline)
        active = backer in pledges
        reason = None
        if before < 0:
            reason = 'after deadline'
        elif action == 'pledge':
            if active:
                reason = 'already pledged'
            elif cents < MIN_PLEDGE:
                reason = 'below minimum'
            else:
                pledges[backer] = [cents, queue]
                queue += 1
        elif not active:
            reason = 'no pledge'
        elif action == 'raise':
            pledges[backer][0] += cents
        elif before < LOCK_DAYS:
            reason = 'locked'
        elif action == 'cancel':
            del pledges[backer]
        elif pledges[backer][0] - cents < MIN_PLEDGE:
            reason = 'below minimum'
        else:
            pledges[backer][0] -= cents
        if reason is not None:
            problems.append((day, backer, reason))
    return (pledges, problems)

def active_pledges(text, deadline):
    """The active pledges at the deadline after replaying the log (events.parse_log, then run_ledger).

    Returns a list of (backer, cents) tuples in queue order (smallest queue number first).

    Valid inputs: text is a log as events.parse_log accepts; deadline is a "YYYY-MM-DD" str.
    """
    pledges = run_ledger(parse_log(text), deadline)[0]
    ordered = sorted(pledges.items(), key=lambda item: item[1][1])
    return [(backer, entry[0]) for backer, entry in ordered]

def event_problems(text, deadline):
    """The ignored events of the log with their reasons (the problems of run_ledger on events.parse_log of text).

    Returns a list of (date, backer, reason) tuples in event order.

    Valid inputs: as active_pledges.
    """
    return run_ledger(parse_log(text), deadline)[1]

