"""Reading CSV text: fields with quotes, and a table with a header row."""

def split_csv_line(line):
    """Split one CSV line into fields at commas, honoring double quotes.

    A field that starts with '"' is quoted: it runs until a '"' that is not followed by another '"', and inside it
    two double quotes in a row stand for one '"' and commas are kept as text. After the closing quote, any
    characters up to the next comma are added to the field as they are. A field that does not start with '"' runs
    to the next comma, quotes included, unchanged. Unquoted fields are stripped of surrounding spaces; quoted
    fields keep their spaces, but spaces before the opening quote are ignored.

    Returns a list of strs (one more than the number of separating commas; "" gives [""]).

    Valid inputs: line is a string of printable ASCII characters and spaces in which every quoted field is closed.
    """
    fields = []
    i = 0
    n = len(line)
    while True:
        while i < n and line[i] == ' ':
            i += 1
        field = ''
        if i < n and line[i] == '"':
            i += 1
            while i < n:
                if line[i] == '"' and i + 1 < n and (line[i + 1] == '"'):
                    field += '"'
                    i += 2
                elif line[i] == '"':
                    i += 1
                    break
                else:
                    field += line[i]
                    i += 1
            end = line.find(',', i)
            end = n if end < 0 else end
            field += line[i:end]
        else:
            end = line.find(',', i)
            end = n if end < 0 else end
            field = line[i:end].strip()
        fields.append(field)
        if end >= n:
            return fields
        i = end + 1

def read_table(lines):
    """Read a table: the first non-blank line is the header, the other non-blank lines are rows.

    A line is blank when it is empty or only spaces. Every line is split with split_csv_line. Each row is cut or
    padded with "" to the length of the header.

    Returns a tuple (header, rows): header is a list of strs, rows a list of lists of strs. When there is no
    non-blank line, returns ([], []).

    Valid inputs: lines is a list of 0 to 30 strings, each valid for split_csv_line.
    """
    header = None
    rows = []
    for line in lines:
        if not line.strip():
            continue
        fields = split_csv_line(line)
        if header is None:
            header = fields
            continue
        fields = fields[:len(header)]
        rows.append(fields + [''] * (len(header) - len(fields)))
    if header is None:
        return ([], [])
    return (header, rows)

