"""Grouping the rows of a table by one column and aggregating another."""
from column_types import column_index, typed_table
OPS = ('sum', 'count', 'mean', 'min', 'max')

def aggregate(values, op):
    """Aggregate a list of cells, ignoring None.

    "count" is the number of non-None values; "sum" their sum (0 when there are none); "mean" the sum divided by
    the count, rounded to 2 decimals with round() (None when there are none); "min" and "max" the smallest and
    largest value (None when there are none).

    Returns an int, float or None.

    Valid inputs: values is a list of ints, floats and None; op is one of OPS.
    """
    present = [v for v in values if v is not None]
    if op == 'count':
        return len(present)
    if op == 'sum':
        return sum(present)
    if not present:
        return None
    if op == 'mean':
        return round(sum(present) / len(present), 2)
    best = present[0]
    for v in present[1:]:
        if op == 'min' and v < best or (op == 'max' and v > best):
            best = v
    return best

def group_key(cell):
    """The text a group is named by: "" for None, str(cell) otherwise.

    Returns a str.

    Valid inputs: cell is an int, float, str or None.
    """
    return '' if cell is None else str(cell)

def group_by(lines, key_column, value_column, op):
    """Group the rows of column_types.typed_table(lines) by key_column and aggregate
    value_column in each group.

    Rows are grouped by group_key of their key cell. When key_column or value_column is not in the header, the
    result is empty.

    Returns a list of (group key str, aggregate) tuples sorted by group key (Python string order).

    Valid inputs: lines as csv_tokens.read_table accepts; key_column and value_column are strs, value_column an
    int or float column when it exists (op "count" also allows a text column); op is one of OPS.
    """
    table = typed_table(lines)
    k, v = (column_index(table, key_column), column_index(table, value_column))
    if k is None or v is None:
        return []
    groups = {}
    for row in table['rows']:
        groups.setdefault(group_key(row[k]), []).append(row[v])
    return [(key, aggregate(groups[key], op)) for key in sorted(groups)]

