TEAM_COUNTED = 3

def team_stage_time(text):
    """Each team's time on one stage: the sum of the TEAM_COUNTED (3) smallest credited times of its finishers
    (stages.stage_results). A team with fewer than 3 finishers gets no time on that stage.

    Returns a dict {team: seconds}.

    Valid inputs: text is a str as stages.parse_stage accepts.
    """
    times = {}
    for _, team, seconds in stage_results(text)[1]:
        times.setdefault(team, []).append(seconds)
    result = {}
    for team, values in times.items():
        if len(values) >= TEAM_COUNTED:
            result[team] = sum(sorted(values)[:TEAM_COUNTED])
    return result

def team_classification(stage_texts):
    """Rank the teams that got a time (team_stage_time) on every stage by the sum of those times; ties go to the
    team with more stage days where it had the smallest team time (shared smallest times count for each such team),
    then to the name that sorts first.

    Returns a list of (team, seconds) tuples, best first; [] when stage_texts is empty.

    Valid inputs: stage_texts is a list of 0 to 6 strs as stages.parse_stage accepts.
    """
    totals = None
    best_days = {}
    for text in stage_texts:
        day = team_stage_time(text)
        if day:
            fastest = min(day.values())
            for team, seconds in day.items():
                if seconds == fastest:
                    best_days[team] = best_days.get(team, 0) + 1
        if totals is None:
            totals = dict(day)
        else:
            totals = {team: totals[team] + day[team] for team in totals if team in day}
    totals = totals or {}
    ranked = sorted(totals, key=lambda team: (totals[team], -best_days.get(team, 0), team))
    return [(team, totals[team]) for team in ranked]

