files.throws.py:
"""Reading darts written as segment codes."""

def parse_dart(code):
    """Parse one dart.

    "S5", "D16", "T20": single, double or treble of a number 1-20 (score n, 2n or 3n; multiplier 1, 2 or 3).
    "SB" is the outer bull (25, multiplier 1), "DB" the bullseye (50, multiplier 2, so it is a double), and "M" a
    miss (0, multiplier 0). Letters may be lower case; surrounding spaces are ignored.

    Returns a tuple (score, multiplier) of ints.

    Valid inputs: code is one of the forms above, with n from 1 to 20.
    """
    code = code.strip().upper()
    if code == 'M':
        return (0, 0)
    if code == 'SB':
        return (25, 1)
    if code == 'DB':
        return (50, 2)
    multiplier = 'SDT'.index(code[0]) + 1
    return (int(code[1:]) * multiplier, multiplier)

def parse_turn(text):
    """Parse a turn: up to three dart codes separated by spaces.

    Returns a list of (score, multiplier) tuples in throwing order (empty for a blank text).

    Valid inputs: text holds 0 to 3 codes as parse_dart accepts, separated by one or more spaces.
    """
    return [parse_dart(code) for code in text.split()]

