"""Caries risk from the tooth chart."""
WISDOM_POSITION = 8

def dmft_counts(marks):
    """The DMFT counts of a tooth chart: decayed, missing and filled teeth.

    Wisdom teeth (position 8: tooth number ending in 8) are not counted. Mark D counts as decayed, M as missing,
    F and C (a crown) both as filled; S (a sealant) is not counted.

    Returns a dict {"D": int, "M": int, "F": int}, all three keys always present.

    Valid inputs: marks is a dict as chart_parse.parse_tooth_marks returns.
    """
    counts = {'D': 0, 'M': 0, 'F': 0}
    for tooth, mark in marks.items():
        if tooth % 10 == WISDOM_POSITION:
            continue
        if mark == 'C':
            mark = 'F'
        if mark in counts:
            counts[mark] += 1
    return counts

def risk_level(marks, age):
    """The caries risk of a patient of `age` years with tooth chart `marks`, from dmft_counts.

    "high" when D is 3 or more, or D is at least 1 and age is under 18, or M is 6 or more;
    otherwise "medium" when D is at least 1, or D + M + F is 10 or more;
    otherwise "low".

    Returns a str.

    Valid inputs: marks as dmft_counts accepts; age is an int from 0 to 120.
    """
    counts = dmft_counts(marks)
    decayed = counts['D']
    if decayed >= 3 or (decayed >= 1 and age < 18) or counts['M'] >= 6:
        return 'high'
    if decayed >= 1 or decayed + counts['M'] + counts['F'] >= 10:
        return 'medium'
    return 'low'

