"""Naming dice poker hands."""
HAND_RANK = {'bust': 0, 'one pair': 1, 'two pair': 2, 'three of a kind': 3, 'five high straight': 4}
HAND_RANK['six high straight'] = 5
HAND_RANK['full house'] = 6
HAND_RANK['four of a kind'] = 7
HAND_RANK['five of a kind'] = 8

def face_counts(dice):
    """How many dice show each face.

    Returns a dict {face: count} for the faces that appear (no zero counts), keys in increasing face order
    (3 3 5 1 5 gives {1: 1, 3: 2, 5: 2}).

    Valid inputs: dice is a list of 1 to 5 ints from 1 to 6.
    """
    counts = {}
    for face in sorted(dice):
        counts[face] = counts.get(face, 0) + 1
    return counts

def classify(dice):
    """The hand of five dice: its name and rank.

    From face_counts: five of one face "five of a kind"; four "four of a kind"; three and two "full house"; three
    and two singles "three of a kind"; two pairs "two pair"; one pair "one pair". Five different faces are
    "six high straight" when they are 2-3-4-5-6, "five high straight" when they are 1-2-3-4-5, and otherwise "bust".
    The rank is HAND_RANK of the name: bust 0, one pair 1, two pair 2, three of a kind 3, five high straight 4, six
    high straight 5, full house 6, four of a kind 7, five of a kind 8.

    Returns a dict {"name": str, "rank": int}.

    Valid inputs: dice is a list of 5 ints from 1 to 6.
    """
    shape = sorted(face_counts(dice).values(), reverse=True)
    if shape[0] == 5:
        name = 'five of a kind'
    elif shape[0] == 4:
        name = 'four of a kind'
    elif shape[0] == 3:
        name = 'full house' if shape[1] == 2 else 'three of a kind'
    elif shape[0] == 2:
        name = 'two pair' if shape[1] == 2 else 'one pair'
    elif sorted(dice) == [2, 3, 4, 5, 6]:
        name = 'six high straight'
    elif sorted(dice) == [1, 2, 3, 4, 5]:
        name = 'five high straight'
    else:
        name = 'bust'
    return {'name': name, 'rank': HAND_RANK[name]}

