"""Cleaning raw DNA text and simple per-base operations."""
COMPLEMENT = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C', 'N': 'N'}

def clean_sequence(text):
    """Turn raw sequence text into a clean DNA string.

    Whitespace characters and the digits 0-9 (FASTA-style position numbers) are removed. Every other character is
    upper-cased; if the upper-cased character is one of A, C, G, T, N it is kept, otherwise it is replaced by "N".
    The order of the kept characters is unchanged.

    Returns a str (empty when nothing is kept).

    Valid inputs: text is a str of ASCII characters.
    """
    out = []
    for ch in text:
        if ch.isspace() or ch.isdigit():
            continue
        up = ch.upper()
        if up in COMPLEMENT:
            out.append(up)
        else:
            out.append('N')
    return ''.join(out)

def reverse_complement(seq):
    """The reverse complement of a clean sequence: reverse the order, then swap A<->T and C<->G (N stays N).

    Returns a str of the same length.

    Valid inputs: seq is a str made only of the letters A, C, G, T, N (possibly empty).
    """
    out = []
    for i in range(len(seq) - 1, -1, -1):
        out.append(COMPLEMENT[seq[i]])
    return ''.join(out)

def gc_percent(seq):
    """The GC content of seq in percent, ignoring N.

    The value is 100 * (number of G and C) / (number of A, C, G and T), rounded with round(x, 2). When seq has no
    A, C, G or T at all (empty, or only N) the result is 0.0.

    Returns a float.

    Valid inputs: seq is a str made only of the letters A, C, G, T, N (possibly empty).
    """
    gc = 0
    known = 0
    for base in seq:
        if base == 'N':
            continue
        known += 1
        if base in 'GC':
            gc += 1
    if known == 0:
        return 0.0
    return round(100 * gc / known, 2)

