"""Running the event log against the guest list, one event at a time."""
import copy
from events import ordered_events
from seating import fits, promote
from states import NEW, next_state
MAX_PLUS = 3

def apply_event(guests, event, capacity):
    """Apply one event to the guest records.

    The guest's current state is their record's "state", or "new" when they have no record. When
    states.next_state(state, action) is None the event is rejected. Otherwise, by action:
    "invite" gives the guest a fresh record {"state": "invited", "plus": 0, "queued": 0, "arrived": 0};
    "accept" with number plus-ones is rejected when number > MAX_PLUS (3); when the guest's party of
    1 + number seats fits (the seats held by everyone except the guest, not counting the guest's own party when they
    are "attending" or "checked_in", plus 1 + number must be at most capacity) the guest becomes "attending" with
    "plus" = number; when it does not fit, a guest who was already attending is rejected (keeping their old seats),
    and anyone else becomes "waitlisted" with "plus" = number and "queued" = the event's seq;
    "checkin" is rejected when number is more than the guest's "plus", else the guest becomes "checked_in" with
    "arrived" = number;
    "maybe" and "decline" just set the state to the next state.
    After every event that is not rejected, waitlisted guests are moved into free seats: they are taken by their
    "queued" seq (equal values in name order); each one whose party of 1 + "plus" seats fits, by the same seat count
    as above, becomes "attending" at once, so later ones see those seats taken; one that does not fit stays
    waitlisted and the next one is tried.

    Returns a tuple (guests dict after the event, accepted bool, list of names promoted). A rejected event gives
    (the input guests, False, []). The input dict is never changed.

    Valid inputs: guests is a dict {name: guest record} with 0 to 20 entries; event is a (seq, guest, action, number)
    tuple as events.parse_event returns, with action in events.ACTIONS; capacity is an int from 0 to 100.
    """
    seq, name, action, number = event
    state = guests[name]['state'] if name in guests else NEW
    after = next_state(state, action)
    if after is None:
        return (guests, False, [])
    new = copy.deepcopy(guests)
    if action == 'invite':
        new[name] = {'state': 'invited', 'plus': 0, 'queued': 0, 'arrived': 0}
    elif action == 'accept':
        if number > MAX_PLUS:
            return (guests, False, [])
        roster = [dict(record, name=key) for key, record in new.items()]
        if fits(roster, name, 1 + number, capacity):
            new[name]['state'] = 'attending'
            new[name]['plus'] = number
        elif state == 'attending':
            return (guests, False, [])
        else:
            new[name]['state'] = 'waitlisted'
            new[name]['plus'] = number
            new[name]['queued'] = seq
    elif action == 'checkin':
        if number > new[name]['plus']:
            return (guests, False, [])
        new[name]['state'] = 'checked_in'
        new[name]['arrived'] = number
    else:
        new[name]['state'] = after
    roster = [dict(record, name=key) for key, record in new.items()]
    moved = promote(roster, capacity)
    after_promote = {}
    for entry in moved['roster']:
        record = dict(entry)
        del record['name']
        after_promote[entry['name']] = record
    return (after_promote, True, moved['promoted'])

def run_events(lines, capacity):
    """Run a whole event log, starting with no guests.

    The events of events.ordered_events(lines) are applied in order with apply_event.

    Returns a dict {"guests": the final guests dict, "rejected": the seq of every rejected event in order,
    "promoted": every promoted name in the order promoted (a name may appear more than once)}.

    Valid inputs: lines is a list of 0 to 30 strings as events.parse_event accepts; capacity is an int from 0 to 100.
    """
    guests = {}
    rejected = []
    promoted = []
    for event in ordered_events(lines):
        guests, accepted, moved = apply_event(guests, event, capacity)
        if not accepted:
            rejected.append(event[0])
        promoted.extend(moved)
    return {'guests': guests, 'rejected': rejected, 'promoted': promoted}

