"""Tests of the new specification. Every test runs and each failure is reported.
Passing them all does not mean the project is correct."""
from api import format_duration, parse_block, parse_duration, parse_plan, parse_step


def same(a, b):
    """Equal values of the same type (True is not 1, a tuple is not a list); floats within a small tolerance."""
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return abs(a - b) <= 1e-9 * max(1.0, abs(a), abs(b))
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return type(a) is type(b) and len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    return type(a) is type(b) and a == b


def short(x):
    r = repr(x)
    return r if len(r) <= 200 else r[:200] + "..."


TESTS = [
    ('parse_duration', parse_duration, ('0s',), {'hours': 0, 'minutes': 0, 'seconds': 0}),
    ('parse_duration', parse_duration, ('1m',), {'hours': 0, 'minutes': 1, 'seconds': 0}),
    ('format_duration', format_duration, ({'hours': 0, 'minutes': 9, 'seconds': 59},), '9:59'),
    ('format_duration', format_duration, ({'hours': 1, 'minutes': 2, 'seconds': 3},), '1:02:03'),
    ('parse_step', parse_step, ('sprint  0M',), ('sprint', 0)),
    ('parse_step', parse_step, ('squats 0:37',), ('squats', 37)),
    ('parse_block', parse_block, ('5X(plank 0:54, rest 92S, plank  1M)',), {'looped': True, 'repeat': 5, 'steps': [('plank', 54), ('rest', 92), ('plank', 60)]}),
    ('parse_block', parse_block, ('1x(work 0:30)',), {'looped': True, 'repeat': 1, 'steps': [('work', 30)]}),
    ('parse_plan', parse_plan, ('Warmup  218s ; 1x(recover  1:43, rest 0M) ; 3X(plank 0:24, work 0m, Rest  6s) ; 3X(Plank 0m, Rest 0M)',), [{'looped': False, 'repeat': 1, 'steps': [('warmup', 218)]}, {'looped': True, 'repeat': 1, 'steps': [('recover', 103), ('rest', 0)]}, {'looped': True, 'repeat': 3, 'steps': [('plank', 24), ('work', 0), ('rest', 6)]}, {'looped': True, 'repeat': 3, 'steps': [('plank', 0), ('rest', 0)]}]),
    ('parse_plan', parse_plan, ('warmup  4:29;3X(plank 82S, Plank 116S, Recover 0M)',), [{'looped': False, 'repeat': 1, 'steps': [('warmup', 269)]}, {'looped': True, 'repeat': 3, 'steps': [('plank', 82), ('plank', 116), ('recover', 0)]}]),
]


def main():
    n = len(TESTS)
    failed = 0
    for k, (name, func, args, want) in enumerate(TESTS):
        shown = name + "(" + ", ".join(short(a) for a in args) + ")"
        if func is None:
            failed += 1
            print(f"FAIL test {k + 1}: {name} is not defined (api.py could not import it)")
            continue
        try:
            got = func(*args)
        except Exception as e:
            failed += 1
            print(f"FAIL test {k + 1}: {shown} raised {type(e).__name__}: {e}; expected {short(want)}")
            continue
        if not same(got, want):
            failed += 1
            print(f"FAIL test {k + 1}: {shown}: expected {short(want)}, got {short(got)}")
    print(f"{n - failed}/{n} tests passed")
    if failed:
        raise SystemExit(1)


main()

