"""One fantasy week: team scores and head-to-head results."""
from lineup import best_lineup, rank_roster
FLEX_SLOT = {'slot': 'FLEX', 'positions': ['RB', 'WR', 'TE']}
SINGLE_SLOTS = ['QB', 'RB', 'RB', 'WR', 'WR', 'TE']
LINEUP_SLOTS = [{'slot': pos, 'positions': [pos]} for pos in SINGLE_SLOTS] + [FLEX_SLOT]

def team_score(lines):
    """A team's score for the week: the sum of the points of its best_lineup (empty slots add 0).

    Returns a float.

    Valid inputs: lines as lineup.rank_roster accepts.
    """
    total = 0.0
    for slot in best_lineup(lines, LINEUP_SLOTS):
        total += slot['points']
    return total

def bench_points(lines):
    """The points left on the bench: the sum of the points of every roster player not in best_lineup.

    Returns a float (0.0 when everyone starts).

    Valid inputs: as team_score.
    """
    starters = {name for slot, name, points in best_lineup(lines) if name is not None}
    total = 0.0
    for name, pos, points in rank_roster(lines):
        if name not in starters:
            total += points
    return total

def matchup(home_lines, away_lines):
    """The result of one game between two rosters.

    Returns a tuple (home score, away score, outcome) where the scores are team_score floats and outcome is "H"
    when the home score is higher, "A" when the away score is higher, "T" when they are equal.

    Valid inputs: home_lines and away_lines each as team_score accepts.
    """
    home = team_score(home_lines)
    away = team_score(away_lines)
    if home > away:
        outcome = 'H'
    elif away > home:
        outcome = 'A'
    else:
        outcome = 'T'
    return (home, away, outcome)

