"""The score of a bout as its events happen, under a rules dict {"weapon": str, "target": int}."""
import copy
from events import parse_events
OTHER_SIDE = {'L': 'R', 'R': 'L'}

def apply_event(state, event, rules):
    """The bout state after one more event.

    A state is a dict {"L": int, "R": int, "yellow": list, "done": bool}: the touches of the left and right fencer,
    the sides ("L"/"R") that already hold a yellow card, in the order they got it, and whether the bout is over.
    rules is a dict {"weapon": weapon, "target": touches to win}. Rules, with target = rules["target"]:
    - once the bout is over, events change nothing;
    - ("touch", side): that side scores 1;
    - ("double", "-"): only when rules["weapon"] is "epee" both sides score 1, except that a double when both sides
      have target - 1 touches is annulled (nothing changes); in "foil" and "sabre" a double changes nothing;
    - ("yellow", side): when the side has no yellow card yet it is added to "yellow"; when it already has one, the
      card counts as a red card instead;
    - ("red", side): the other side scores 1.
    After the event, "done" is True when either side has `target` touches or more.

    Returns a new dict; `state` is not changed.

    Valid inputs: state is a dict as described; event is a tuple as events.parse_events returns; rules is a dict
    with "weapon" one of "foil", "epee", "sabre" and "target" an int from 1 to 15.
    """
    new = copy.deepcopy(state)
    if new['done']:
        return new
    target = rules['target']
    kind, side = event
    if kind == 'touch':
        new[side] += 1
    elif kind == 'double':
        both_last = new['L'] == target - 1 and new['R'] == target - 1
        if rules['weapon'] == 'epee' and (not both_last):
            new['L'] += 1
            new['R'] += 1
    elif kind == 'yellow' and side not in new['yellow']:
        new['yellow'].append(side)
    else:
        new[OTHER_SIDE[side]] += 1
    new['done'] = new['L'] >= target or new['R'] >= target
    return new

def run_bout(events, rules):
    """The final state of a bout: apply_event for every event in order, starting from
    {"L": 0, "R": 0, "yellow": [], "done": False}.

    Returns a state dict as apply_event returns.

    Valid inputs: events is a list as events.parse_events returns; rules as apply_event accepts.
    """
    state = {'L': 0, 'R': 0, 'yellow': [], 'done': False}
    for event in events:
        state = apply_event(state, event, rules)
    return state

def bout_result(text, rules):
    """The result of a bout from its event codes (events.parse_events, then run_bout).

    The winner is the side that reached the target; when the bout is not over (time ran out), the side with more
    touches wins, and with equal touches there is no winner.

    Returns a dict {"left": left touches, "right": right touches, "winner": "L", "R" or None}.

    Valid inputs: text as events.parse_events accepts; rules as apply_event accepts.
    """
    state = run_bout(parse_events(text), rules)
    result = {'left': state['L'], 'right': state['R'], 'winner': None}
    if state['L'] > state['R']:
        result['winner'] = 'L'
    elif state['R'] > state['L']:
        result['winner'] = 'R'
    return result

