"""Reading the referee's event codes for one bout."""
TOUCH_CODES = {'L': ('touch', 'L'), 'R': ('touch', 'R'), 'D': ('double', '-')}
CARD_KINDS = {'Y': 'yellow', 'C': 'red'}

def parse_events(text):
    """Parse the events of a bout, written as codes separated by spaces (case does not matter).

    "L" is a touch scored by the left fencer, "R" one scored by the right fencer, "D" a double touch (both hit at
    once). A card is "Y" (yellow) or "C" (red) followed by the side it is given to, "L" or "R" (for example "YL" is a
    yellow card for the left fencer). Codes that are none of these are skipped.

    Returns a list of (kind, side) tuples in order: ("touch", "L"), ("touch", "R"), ("double", "-"),
    ("yellow", "L"|"R") or ("red", "L"|"R").

    Valid inputs: text is a string of 0 to 60 codes separated by one or more spaces.
    """
    out = []
    for code in text.upper().split():
        if code in TOUCH_CODES:
            out.append(TOUCH_CODES[code])
        elif len(code) == 2 and code[0] in CARD_KINDS and (code[1] in 'LR'):
            out.append((CARD_KINDS[code[0]], code[1]))
    return out

