"""Moves on the floor grid and walking distances from a set of starting cells."""
DIRECTIONS = [('N', -1, 0), ('W', 0, -1), ('E', 0, 1), ('S', 1, 0)]

def step_options(plan, cell, blocked):
    """The cells one step from `cell`: north, west, east, south, in this order (north is the row above).

    A neighbor is left out when it is outside the grid, a wall, or in `blocked`.

    Returns a list of (direction, (row, column)) tuples, direction being "N", "W", "E" or "S".

    Valid inputs: plan is a dict as floor_plan.parse_floor returns; cell is a (row, column) tuple inside the grid;
    blocked is a list of (row, column) tuples.
    """
    out = []
    for name, dr, dc in DIRECTIONS:
        r, c = (cell[0] + dr, cell[1] + dc)
        if 0 <= r < plan['height'] and 0 <= c < plan['width']:
            if (r, c) not in plan['walls'] and (r, c) not in blocked:
                out.append((name, (r, c)))
    return out

def walk_distances(plan, sources, blocked):
    """The number of steps from each cell to the nearest of `sources`, walking north, west, east or south.

    Walls and the cells in `blocked` cannot be entered or crossed. The sources are at distance 0.

    Returns a dict {(row, column): steps} with every cell that can reach a source (blocked cells, unless they are
    sources, and walls are never in it).

    Valid inputs: plan as step_options accepts; sources is a list of distinct (row, column) cells that are not
    walls; blocked is a list of (row, column) cells.
    """
    dist = {cell: 0 for cell in sources}
    queue = list(sources)
    for cell in queue:
        for _, nxt in step_options(plan, cell, blocked):
            if nxt not in dist:
                dist[nxt] = dist[cell] + 1
                queue.append(nxt)
    return dist

