files.plays.py:
"""Reading pass plays from a play-by-play sheet."""

def parse_game_clock(text):
    """Parse the game clock "MM:SS" (time left in the quarter).

    Returns an int: seconds left ("08:41" -> 521, "0:07" -> 7, "15:00" -> 900).

    Valid inputs: text is one or two digits for minutes 0-15, ":", two digits for seconds 0-59.
    """
    minutes, seconds = text.split(':')
    return int(minutes) * 60 + int(seconds)

def parse_play(line):
    """Parse one pass play "Qn MM:SS D&DIST WHO RESULT [YARDS] [TD]".

    Tokens are separated by one or more spaces:
    - "Qn": the quarter n (5 is overtime); "MM:SS": the game clock (parse_game_clock);
    - "D&DIST": the down and the yards to go, e.g. "3&7";
    - WHO: "PASSER>TARGET" for a throw to a receiver, or just "PASSER" (players are written "TEAM#NUMBER");
    - RESULT: "C" complete, "I" incomplete, "X" intercepted, "S" sacked;
    - YARDS: a signed whole number (e.g. "12", "-7", "+3"), present only when the play has yards; it is 0 when left
      out;
    - "TD": present as the last token when the play scored a touchdown.

    Returns a dict of three parts:
    {"when": {"quarter": int, "clock": int (seconds)},
     "situation": {"down": int, "distance": int},
     "throw": {"passer": str, "target": str or None, "result": str, "yards": int, "td": bool}}.

    Valid inputs: line follows the format above with at least five tokens; the numbers are digits (YARDS may start
    with "+" or "-").
    """
    tokens = line.split()
    down, distance = tokens[2].split('&')
    who = tokens[3].split('>')
    td = tokens[-1] == 'TD'
    rest = tokens[5:-1] if td else tokens[5:]
    when = {'quarter': int(tokens[0][1:]), 'clock': parse_game_clock(tokens[1])}
    situation = {'down': int(down), 'distance': int(distance)}
    throw = {'passer': who[0], 'target': who[1] if len(who) == 2 else None, 'result': tokens[4]}
    throw['yards'] = int(rest[0]) if rest else 0
    throw['td'] = td
    return {'when': when, 'situation': situation, 'throw': throw}

def play_problem(play):
    """The first reason a parsed play is not a valid pass play, or None.

    Checks in this order (each field read from its part of the play): "bad quarter" (quarter not 1-5); "bad down" (down not 1-4); "bad distance" (distance not
    1-99); "bad result" (result not one of C, I, X, S); "no target" (C, I or X without a target; a pass thrown away is
    written with a target too); "sack with target" (S with a target); "sack gain" (S with yards above 0);
    "td without catch" (td on a play that is not C); "yards on miss" (I or X with yards not 0).

    Returns a str or None.

    Valid inputs: play is a dict as parse_play returns.
    """
    if not 1 <= play['when']['quarter'] <= 5:
        return 'bad quarter'
    if not 1 <= play['situation']['down'] <= 4:
        return 'bad down'
    if not 1 <= play['situation']['distance'] <= 99:
        return 'bad distance'
    throw = play['throw']
    if throw['result'] not in ['C', 'I', 'X', 'S']:
        return 'bad result'
    thrown = throw['result'] != 'S'
    if thrown and throw['target'] is None:
        return 'no target'
    if not thrown and throw['target'] is not None:
        return 'sack with target'
    if not thrown and throw['yards'] > 0:
        return 'sack gain'
    if throw['td'] and throw['result'] != 'C':
        return 'td without catch'
    if throw['result'] in ['I', 'X'] and throw['yards'] != 0:
        return 'yards on miss'
    return None

