"""The shipping container types on offer: inner size, payload and freight rate."""
from geometry import volume_litres
KINDS = ['20GP', '40GP', '40HC']
INNER_CM = {'20GP': (589, 235, 239), '40GP': (1203, 235, 239), '40HC': (1203, 235, 269)}
PAYLOAD_KG = {'20GP': 28200, '40GP': 26700, '40HC': 26500}
RATE_CENTS = {'20GP': 185000, '40GP': 295000, '40HC': 315000}

def container_spec(kind):
    """The figures of one container type, from INNER_CM, PAYLOAD_KG and RATE_CENTS.

    Returns a dict {"inner_cm": {"length": int, "width": int, "height": int}, "payload_kg": int, "rate_cents": int}
    with the inner size in centimetres, the payload in kilograms and the freight rate per container in cents:
    "20GP" is 589 x 235 x 239 cm, 28200 kg, 185000 cents; "40GP" is 1203 x 235 x 239 cm, 26700 kg, 295000 cents;
    "40HC" is 1203 x 235 x 269 cm, 26500 kg, 315000 cents.

    Valid inputs: kind is one of KINDS.
    """
    length, width, height = INNER_CM[kind]
    inner = {'length': length, 'width': width, 'height': height}
    return {'inner_cm': inner, 'payload_kg': PAYLOAD_KG[kind], 'rate_cents': RATE_CENTS[kind]}

def container_volume(kind):
    """The inner volume of a container type in litres: geometry.volume_litres of its inner size.

    Returns an int (33081 for "20GP").

    Valid inputs: kind is one of KINDS.
    """
    return volume_litres(INNER_CM[kind])

