"""Applying events to card balances: the card state machine."""
import copy
from card_dates import add_years, parse_iso
from events import parse_log
MIN_LOAD = 500
MAX_BALANCE = 50000
EXPIRY_YEARS = 5

def apply_event(cards, event):
    """Apply one event to the cards and say whether it was accepted.

    cards maps a card id to {"balance": int cents, "status": "active" or "void", "issued": date str, "last_use":
    date str}. The input dict is not changed; the result is a new dict (a deep copy, changed when accepted).

    The checks and effects, in this order (the first failing check gives the reason, and the cards stay as they were):
    ISSUE: "exists" when the card is already in cards; "amount" when the amount is below MIN_LOAD (500) or above
    MAX_BALANCE (50000). Else the card is added with balance = amount, status "active", issued and last_use = the
    event date.
    Any other kind: "unknown card" when the card is not in cards; "void" when its status is "void"; "expired" when
    the event date is on or after the expiry date, EXPIRY_YEARS (5) years after the issue date (the same month and day;
    February 29 becomes February 28 when that year is not a leap year). Then by kind:
    RELOAD: "amount" when the amount is below MIN_LOAD; "limit" when balance + amount is above MAX_BALANCE. Else the
    amount is added.
    REDEEM: "empty" when the balance is 0. Else min(balance, amount) is taken off (a partial redemption when the
    balance is short).
    REFUND: the balance becomes min(balance + amount, MAX_BALANCE).
    VOID: the status becomes "void"; the balance is kept and last_use does not change.
    An accepted RELOAD, REDEEM or REFUND sets last_use to the event date.

    Returns a tuple (new cards dict, reason): reason is None when the event was accepted, else one of the strs above.

    Valid inputs: cards is a dict as described (dates valid "YYYY-MM-DD", years 1900-2090, balances 0 to 50000);
    event is a dict as events.parse_event returns, with kind one of ISSUE, RELOAD, REDEEM, REFUND, VOID.
    """
    out = copy.deepcopy(cards)
    kind = event['kind']
    card = event['card']
    amount = event['amount']
    if kind == 'ISSUE':
        if card in out:
            return (out, 'exists')
        if amount < MIN_LOAD or amount > MAX_BALANCE:
            return (out, 'amount')
        when = event['date']
        out[card] = {'balance': amount, 'status': 'active', 'issued': when, 'last_use': when}
        return (out, None)
    if card not in out:
        return (out, 'unknown card')
    state = out[card]
    if state['status'] == 'void':
        return (out, 'void')
    if event['date'] >= add_years(state['issued'], EXPIRY_YEARS):
        return (out, 'expired')
    if kind == 'VOID':
        state['status'] = 'void'
        return (out, None)
    if kind == 'RELOAD':
        if amount < MIN_LOAD:
            return (out, 'amount')
        if state['balance'] + amount > MAX_BALANCE:
            return (out, 'limit')
        state['balance'] += amount
    elif kind == 'REDEEM':
        if state['balance'] == 0:
            return (out, 'empty')
        state['balance'] -= min(state['balance'], amount)
    else:
        state['balance'] = min(state['balance'] + amount, MAX_BALANCE)
    state['last_use'] = event['date']
    return (out, None)

def replay(lines):
    """Apply every event of a log, in parse_log order, starting from no cards.

    Returns a tuple (cards, rejected): cards is the final dict as apply_event returns; rejected is the list of
    (date, card, reason) tuples of the rejected events, in the order they were applied.

    Valid inputs: lines as events.parse_log accepts, with dates in years 1900-2090.
    """
    cards = {}
    rejected = []
    for event in parse_log(lines):
        cards, reason = apply_event(cards, event)
        if reason is not None:
            rejected.append((event['date'], event['card'], reason))
    return (cards, rejected)

