"""Reading coupons and working out what one coupon is worth on one cart item."""
from cart import parse_cents

def parse_coupon(text):
    """Parse a coupon "ISSUER|TARGET|OFFER".

    Fields are stripped of surrounding spaces. ISSUER is "M" (manufacturer) or "S" (store), either case, and is
    returned in upper case. TARGET is a SKU, "dept:NAME" (every item of that department; NAME is turned to lower
    case) or "*" (the whole basket). OFFER, by kind:
    "D.CCxN" or "D.CC": "off", D.CC cents off each unit for at most N units (N is 1 when "xN" is missing);
    "P%": "pct", P percent off;
    "BOGO" (either case): "bogo", buy one get one free;
    "D.CC/E.EE": "basket", D.CC off a basket of at least E.EE (only with target "*").

    Returns a dict {"issuer": str, "target": str, "kind": str, "value": int (cents for off and basket, the percent
    for pct, 0 for bogo), "limit": int (N for off, else 0), "min": int (E.EE in cents for basket, else 0)}.

    Valid inputs: text has exactly two "|" and fields as described; P is an int from 1 to 100; N is from 1 to 9; the
    target is "*" exactly when the offer is a basket offer, and then the issuer is "S" (either case).
    """
    issuer, target, offer = [part.strip() for part in text.split('|')]
    if target.lower().startswith('dept:'):
        target = 'dept:' + target[5:].lower()
    out = {'issuer': issuer.upper(), 'target': target, 'kind': 'off', 'value': 0, 'limit': 0, 'min': 0}
    if offer.upper() == 'BOGO':
        out['kind'] = 'bogo'
    elif offer.endswith('%'):
        out['kind'] = 'pct'
        out['value'] = int(offer[:-1])
    elif '/' in offer:
        off, least = offer.split('/')
        out['kind'] = 'basket'
        out['value'] = parse_cents(off)
        out['min'] = parse_cents(least)
    else:
        amount, _, limit = offer.partition('x')
        out['value'] = parse_cents(amount)
        out['limit'] = int(limit) if limit else 1
    return out

def coupon_applies(coupon, item):
    """Does the coupon cover the item? True when the target is the item's SKU, or "dept:" followed by the item's
    dept; basket coupons ("*") never cover a single item.

    Returns a bool.

    Valid inputs: coupon is a dict as parse_coupon returns; item a dict as cart.parse_item returns.
    """
    if coupon['target'] == '*':
        return False
    if coupon['target'].startswith('dept:'):
        return coupon['target'][5:] == item['dept']
    return coupon['target'] == item['sku']

def coupon_value(coupon, item, left):
    """What the coupon takes off an item whose price still to pay is `left` cents (0 when it does not apply).

    "off": value * min(limit, qty); "pct": left * value // 100 (rounded down); "bogo": every second unit is free,
    (qty // 2) * unit. The result is never more than left. A coupon that does not apply (coupon_applies) or a basket
    coupon is worth 0.

    Returns an int (cents).

    Valid inputs: coupon and item as coupon_applies accepts; left is an int from 0 to item["total"].
    """
    if not coupon_applies(coupon, item):
        return 0
    if coupon['kind'] == 'off':
        value = coupon['value'] * min(coupon['limit'], item['qty'])
    elif coupon['kind'] == 'pct':
        value = left * coupon['value'] // 100
    else:
        value = item['qty'] // 2 * item['unit']
    return min(value, left)

