"""Placing blocks of participants on teams, strongest blocks first."""
from strength import team_profile

def block_order(blocks, index):
    """The order in which blocks are placed: higher total level first, then bigger blocks, then by first name.

    Returns a list of blocks (each the same list as given).

    Valid inputs: blocks is a list of 0 to 30 non-empty sorted lists of names, each name a key of index; index is a
    dict as roster.build_index returns.
    """
    return sorted(blocks, key=lambda block: (-team_profile(block, index)['strength'], -len(block), block[0]))

def allocate_blocks(blocks, index, n_teams, max_size):
    """Place every block on one of n_teams teams, numbered from 0.

    Blocks are taken in block_order. A block goes to the team, among those it fits on (team size + block size at
    most max_size), with the lowest total level so far; ties go to the team with fewer members, then the lower
    team number. A block that fits on no team goes to the waiting list.

    Returns a tuple (teams, waiting): teams is a list of n_teams sorted lists of names; waiting is a sorted list of
    names.

    Valid inputs: blocks and index as block_order accepts, no name in two blocks; n_teams is an int from 1 to 6;
    max_size is an int from 1 to 6.
    """
    teams = [[] for _ in range(n_teams)]
    waiting = []
    for block in block_order(blocks, index):
        best = None
        for t, team in enumerate(teams):
            if len(team) + len(block) > max_size:
                continue
            key = (team_strength(team, index), len(team), t)
            if best is None or key < best:
                best = key
        if best is None:
            waiting.extend(block)
        else:
            teams[best[2]] = sorted(teams[best[2]] + block)
    return (teams, sorted(waiting))

