"""Key codes ("KW1-35274") and whether they can be cut."""
from blanks import blank_spec

def parse_key_code(code):
    """Split a key code "KEYWAY-DIGITS" into its keyway and its depth numbers.

    The keyway is the part before the "-", stripped of spaces and upper-cased; each character of the part after it
    (stripped of spaces) is one cut's depth number, from the bow (the head of the key) to the tip.

    Returns a tuple (keyway, depths): keyway a str, depths a list of ints.

    Valid inputs: code is a str with exactly one "-"; before it 1 to 4 letters and digits, after it 1 to 8 digits
    (either part may have spaces around it).
    """
    keyway, digits = code.split('-')
    return (keyway.strip().upper(), [int(ch) for ch in digits.strip()])

def bitting_problem(code):
    """Why a key code cannot be cut, or None when it can.

    The checks, in this order, the first failing one giving the answer (the keyway's values come from the blank
    catalog in module blanks: the number of cuts, the lowest and highest depth number and the MACS):
    "unknown keyway" when the store does not stock the keyway;
    "needs N cuts" when the code does not have exactly N cuts, N being the keyway's number of cuts;
    "depth at P" for the first cut (P counted from 1 at the bow) whose depth number is below the lowest or above
    the highest depth number of the keyway;
    "MACS at P" for the first pair of neighboring cuts whose depth numbers differ by more than the keyway's MACS
    (P is the position of the second cut of the pair).

    Returns a str or None.

    Valid inputs: code is a key code as parse_key_code accepts.
    """
    keyway, depths = parse_key_code(code)
    spec = blank_spec(keyway)
    if spec is None:
        return 'unknown keyway'
    cuts, lowest, highest, macs = spec
    if len(depths) != cuts:
        return f'needs {cuts} cuts'
    for pos, depth in enumerate(depths):
        if depth < lowest or depth > highest:
            return f'depth at {pos + 1}'
    for pos in range(1, len(depths)):
        if abs(depths[pos] - depths[pos - 1]) > macs:
            return f'MACS at {pos + 1}'
    return None

files.blanks.py:
"""The catalog of key blanks the store cuts: cut counts, depth numbers, MACS and cut heights per keyway."""
KEYWAYS = ['KW1', 'SC1', 'SC4', 'Y1']
PIN_COUNT = {'KW1': 5, 'SC1': 5, 'SC4': 6, 'Y1': 5}
LOWEST_DEPTH = {'KW1': 1, 'SC1': 0, 'SC4': 0, 'Y1': 0}
HIGHEST_DEPTH = {'KW1': 7, 'SC1': 9, 'SC4': 9, 'Y1': 9}
MACS = {'KW1': 4, 'SC1': 7, 'SC4': 7, 'Y1': 6}
TOP_HEIGHT = {'KW1': 329, 'SC1': 335, 'SC4': 335, 'Y1': 320}
DEPTH_STEP = {'KW1': 23, 'SC1': 15, 'SC4': 15, 'Y1': 19}

def blank_spec(keyway):
    """The catalog entry of a keyway, or None when the store does not stock it.

    Keyway: cuts, lowest depth, highest depth, MACS (maximum adjacent cut specification), top height, step:
    KW1: 5, 1, 7, 4, 329, 23; SC1: 5, 0, 9, 7, 335, 15; SC4: 6, 0, 9, 7, 335, 15; Y1: 5, 0, 9, 6, 320, 19.

    Returns a dict {"keyway": str, "cuts": int, "depths": list of ints, "macs": int, "top": int, "step": int} or
    None. "depths" lists every depth number of the keyway, from the lowest to the highest, ascending; "top" is the
    blade height left at the lowest depth number and "step" what each depth number deeper removes, both in
    thousandths of an inch.

    Valid inputs: keyway is a str of 1 to 4 characters.
    """
    if keyway not in KEYWAYS:
        return None
    depths = list(range(LOWEST_DEPTH[keyway], HIGHEST_DEPTH[keyway] + 1))
    spec = {'keyway': keyway, 'cuts': PIN_COUNT[keyway], 'depths': depths, 'macs': MACS[keyway]}
    spec['top'] = TOP_HEIGHT[keyway]
    spec['step'] = DEPTH_STEP[keyway]
    return spec

def cut_height(spec, depth):
    """The height of the blade left at a cut of depth number `depth`, in thousandths of an inch.

    The lowest depth number leaves the top height, and each depth number deeper removes one step:
    spec["top"] - (depth - lowest depth number) * spec["step"].

    Returns an int.

    Valid inputs: spec is a dict as blank_spec returns (not None); depth is one of spec["depths"].
    """
    return spec['top'] - (depth - spec['depths'][0]) * spec['step']

