"""Calendar dates written "YYYY-MM-DD" and as {"year", "month", "day"} dicts."""
MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

def is_leap(year):
    """Is `year` a leap year in the Gregorian calendar (divisible by 4 and not by 100, or divisible by 400)?

    Returns a bool.

    Valid inputs: year is an int from 1 to 9999.
    """
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def days_in_month(date):
    """The number of days in the month of `date`: 31, 30, or for February 28, or 29 in a leap year. Only the
    "year" and "month" of the dict are used.

    Returns an int.

    Valid inputs: date is a dict {"year": int 1-9999, "month": int 1-12, "day": int}.
    """
    if date['month'] == 2 and is_leap(date['year']):
        return 29
    return MONTH_DAYS[date['month'] - 1]

def parse_iso(text):
    """Parse a date "YYYY-MM-DD".

    Returns a dict {"year": int, "month": int, "day": int}.

    Valid inputs: text is four digits, "-", two digits, "-", two digits, naming a date that exists, year 1-9998.
    """
    year, month, day = text.split('-')
    return {'year': int(year), 'month': int(month), 'day': int(day)}

def next_day(date):
    """The calendar day after `date`.

    Returns a new dict {"year": int, "month": int, "day": int}.

    Valid inputs: date is a dict {"year", "month", "day"} of ints naming a date that exists, year 1-9998.
    """
    year, month, day = (date['year'], date['month'], date['day'])
    if day < days_in_month(date):
        return {'year': year, 'month': month, 'day': day + 1}
    if month < 12:
        return {'year': year, 'month': month + 1, 'day': 1}
    return {'year': year + 1, 'month': 1, 'day': 1}

def format_iso(date):
    """Write a date as "YYYY-MM-DD" with a four-digit year and two-digit month and day.

    Returns a str.

    Valid inputs: date is a dict {"year", "month", "day"} of ints naming a date that exists, year 1-9999.
    """
    return f"{date['year']:04d}-{date['month']:02d}-{date['day']:02d}"

