"""Reading hostel booking lines "guest | gender | arrival date | nights | bunk preference"."""
from datetime import date
GENDERS = ['F', 'M', 'X']
PREFS = ['lower', 'upper', 'any']
MAX_NIGHTS = 14

def parse_booking(line):
    """Parse one booking line "guest|gender|arrive|nights|pref".

    Every field is stripped of surrounding spaces; gender is upper-cased and pref lower-cased.

    Returns a dict with keys "guest" (str), "gender" (str), "arrive" (the "YYYY-MM-DD" str of the first night),
    "nights" (int) and "pref" (str).

    Valid inputs: line is a string that booking_problem accepts (returns None for).
    """
    guest, gender, arrive, nights, pref = [part.strip() for part in line.split('|')]
    record = {'guest': guest, 'gender': gender.upper(), 'arrive': arrive}
    record['nights'] = int(nights)
    record['pref'] = pref.lower()
    return record

def booking_problem(line):
    """Why a booking line is not valid, or None when it is.

    The checks, in this order, the first failing one giving the answer (fields are stripped of surrounding spaces
    first):
    "fields" when the line does not have exactly 5 "|"-separated fields;
    "guest" when the guest field is empty;
    "gender" when the gender, upper-cased, is not one of "F", "M", "X";
    "date" when the arrival is not a real calendar date written as "YYYY-MM-DD" (exactly 10 characters, digits in
    every place except the two "-" at positions 4 and 7);
    "nights" when the nights field is not made of digits only, or its value is below 1 or above MAX_NIGHTS (14);
    "pref" when the preference, lower-cased, is not one of "lower", "upper", "any".

    Returns a str or None.

    Valid inputs: line is any string.
    """
    parts = [part.strip() for part in line.split('|')]
    if len(parts) != 5:
        return 'fields'
    guest, gender, arrive, nights, pref = parts
    if guest == '':
        return 'guest'
    if gender.upper() not in GENDERS:
        return 'gender'
    shape_ok = len(arrive) == 10 and arrive[4] == '-' and (arrive[7] == '-')
    digits = arrive[:4] + arrive[5:7] + arrive[8:]
    if not shape_ok or not digits.isdigit():
        return 'date'
    try:
        date(int(arrive[:4]), int(arrive[5:7]), int(arrive[8:]))
    except ValueError:
        return 'date'
    if not nights.isdigit() or int(nights) < 1 or int(nights) > MAX_NIGHTS:
        return 'nights'
    if pref.lower() not in PREFS:
        return 'pref'
    return None

def valid_bookings(lines):
    """Split booking lines into the valid bookings and the rejected lines.

    Returns a tuple (bookings, rejects): bookings is a list of parsed booking dicts (as parse_booking returns) for
    the valid lines, in input order; rejects is a list of (line number counted from 1, problem str) tuples for the
    invalid lines, in input order.

    Valid inputs: lines is a list of strings.
    """
    bookings = []
    rejects = []
    for number, line in enumerate(lines, start=1):
        problem = booking_problem(line)
        if problem is None:
            bookings.append(parse_booking(line))
        else:
            rejects.append((number, problem))
    return (bookings, rejects)

