"""How much concentrate, water or pH adjuster a reservoir needs."""
from stages import stage_targets
EC_PER_ML_PER_10L = 5
PH_ML_PER_100L = 1

def ceil_div(a, b):
    """a / b rounded up to a whole number.

    Returns an int.

    Valid inputs: a is an int >= 0; b an int >= 1.
    """
    return -(-a // b)

def ec_action(ec, vol, capacity, low, high):
    """The EC correction for a reservoir, aiming at the middle of the range, mid = (low + high) // 2.

    EC below low: ("feed", ml) with ml = ceil((mid - ec) * vol / 50) of concentrate (1 ml per 10 liters raises EC
    by EC_PER_ML_PER_10L (5) hundredths). EC above high: ("water", liters) with liters =
    ceil(vol * (ec - mid) / mid) of fresh water, when that fits in the free space capacity - vol; when it does not
    fit: ("change", 0), a full reservoir change. Otherwise (low <= ec <= high): ("ok", 0).

    Returns a tuple (str, int).

    Valid inputs: ec is an int from 0 to 500; vol an int from 1 to 500; capacity an int >= vol; low and high ints
    with 0 < low < high.
    """
    mid = (low + high) // 2
    if ec < low:
        return ('feed', ceil_div((mid - ec) * vol, 10 * EC_PER_ML_PER_10L))
    if ec > high:
        liters = ceil_div(vol * (ec - mid), mid)
        if liters > capacity - vol:
            return ('change', 0)
        return ('water', liters)
    return ('ok', 0)

def ph_action(ph, vol, low, high):
    """The pH correction for a reservoir, aiming at mid = (low + high) // 2.

    pH below low: ("ph_up", ml); above high: ("ph_down", ml); with ml = ceil(|ph - mid| * vol / 100)
    (PH_ML_PER_100L (1) ml per 100 liters moves the pH by 0.01). Otherwise ("ok", 0).

    Returns a tuple (str, int).

    Valid inputs: ph is an int from 300 to 1000; vol an int from 1 to 500; low and high ints with low < high.
