"""How much concentrate, water or pH adjuster a reservoir needs."""
from stages import stage_targets
EC_PER_ML_PER_10L = 5
PH_ML_PER_100L = 1

def ceil_div(a, b):
    """a / b rounded up to a whole number.

    Returns an int.

    Valid inputs: a is an int >= 0; b an int >= 1.
    """
    return -(-a // b)

def ec_action(ec, vol, capacity, low, high):
    """The EC correction for a reservoir, aiming at the middle of the range, mid = (low + high) // 2.

    EC below low: ("feed", ml) with ml = ceil((mid - ec) * vol / 50) of concentrate (1 ml per 10 liters raises EC
    by EC_PER_ML_PER_10L (5) hundredths). EC above high: ("water", liters) with liters =
    ceil(vol * (ec - mid) / mid) of fresh water, when that fits in the free space capacity - vol; when it does not
    fit: ("change", 0), a full reservoir change. Otherwise (low <= ec <= high): ("ok", 0).

    Returns a tuple (str, int).

    Valid inputs: ec is an int from 0 to 500; vol an int from 1 to 500; capacity an int >= vol; low and high ints
    with 0 < low < high.
    """
    mid = (low + high) // 2
    if ec < low:
        return ('feed', ceil_div((mid - ec) * vol, 10 * EC_PER_ML_PER_10L))
    if ec > high:
        liters = ceil_div(vol * (ec - mid), mid)
        if liters > capacity - vol:
            return ('change', 0)
        return ('water', liters)
    return ('ok', 0)

def ph_action(ph, vol, low, high):
    """The pH correction for a reservoir, aiming at mid = (low + high) // 2.

    pH below low: ("ph_up", ml); above high: ("ph_down", ml); with ml = ceil(|ph - mid| * vol / 100)
    (PH_ML_PER_100L (1) ml per 100 liters moves the pH by 0.01). Otherwise ("ok", 0).

    Returns a tuple (str, int).

    Valid inputs: ph is an int from 300 to 1000; vol an int from 1 to 500; low and high ints with low < high.
    """
    mid = (low + high) // 2
    if ph < low:
        return ('ph_up', ceil_div((mid - ph) * vol * PH_ML_PER_100L, 100))
    if ph > high:
        return ('ph_down', ceil_div((ph - mid) * vol * PH_ML_PER_100L, 100))
    return ('ok', 0)

def tank_correction(reading, crop, age, capacity):
    """The corrections one reading needs, for a crop at an age in days and a reservoir capacity in liters.

    The EC and pH ranges are the targets of the crop's growth stage at that age (the table in stages.py). The EC
    action (see ec_action) comes first, then the pH action (see ph_action), except that after a "change" the pH is not
    corrected (the reservoir is refilled). Actions "ok" are left out; each other action is written "name amount"
    with the unit "ml" ("feed", "ph_up", "ph_down") or "L" ("water"), e.g. "feed 48 ml", "water 12 L"; a change is
    written "change". When nothing is needed the list is ["ok"].

    Returns a list of str.

    Valid inputs: reading is a dict as readings.parse_reading returns; crop is "lettuce", "basil", "tomato" or
    "strawberry"; age an int from 0 to 400; capacity an int >= reading["vol"].
    """
    targets = stage_targets(crop, age)
    ec_low, ec_high = targets['ec']
    ph_low, ph_high = targets['ph']
    ec_name, ec_amount = ec_action(reading['ec'], reading['vol'], capacity, ec_low, ec_high)
    out = []
    if ec_name == 'change':
        return ['change']
    if ec_name == 'feed':
        out.append(f'feed {ec_amount} ml')
    elif ec_name == 'water':
        out.append(f'water {ec_amount} L')
    ph_name, ph_amount = ph_action(reading['ph'], reading['vol'], ph_low, ph_high)
    if ph_name != 'ok':
        out.append(f'{ph_name} {ph_amount} ml')
    return out if out else ['ok']

