from api import age_in_years, bonus_points, language_level, overall_band, points_breakdown, work_months


def same(a, b):
    """Equal values of the same type (True is not 1, a tuple is not a list); floats within a small tolerance."""
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return abs(a - b) <= 1e-9 * max(1.0, abs(a), abs(b))
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return type(a) is type(b) and len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    return type(a) is type(b) and a == b


def short(x):
    r = repr(x)
    return r if len(r) <= 200 else r[:200] + "..."


TESTS = [
    ('age_in_years', age_in_years, (23884, 24292), 34),
    ('age_in_years', age_in_years, (23884, 24293), 34),
    ('work_months', work_months, ([(24120, 24187)], 24306), 1),
    ('work_months', work_months, ([(24240, 24263), (24257, 24269), (24258, 24260)], 24306), 30),
    ('overall_band', overall_band, ((6.0, 7.5, 8.0, 7.0),), 7.0),
    ('overall_band', overall_band, ((8.5, 7.0, 7.5, 9.0),), 8.0),
    ('language_level', language_level, ((6.0, 6.0, 6.0, 5.5),), 'competent'),
    ('language_level', language_level, ((7.5, 8.0, 5.5, 6.0),), 'competent'),
    ('bonus_points', bonus_points, ([], 'master'), 0),
    ('bonus_points', bonus_points, (['offer'], 'doctorate'), 10),
    ('points_breakdown', points_breakdown, ({'name': 'Ana', 'occupation': 'engineer', 'birth': (1989, 3), 'education': 'diploma', 'bands': (7.5, 6.0, 7.0, 7.0), 'work': [((2018, 7), (2019, 8)), ((2013, 6), (2015, 9)), ((2014, 2), (2014, 12))], 'flags': ['regional'], 'lodged': (2025, 1)}, (2025, 7)), {'age': 25, 'bonus': 15, 'education': 10, 'experience': 0, 'language': 0, 'total': 50}),
    ('points_breakdown', points_breakdown, ({'name': 'Rosa', 'occupation': 'chef', 'birth': (1997, 12), 'education': 'bachelor', 'bands': (8.0, 8.0, 9.0, 9.0), 'work': [], 'flags': ['offer', 'sponsor', 'study'], 'lodged': (2025, 7)}, (2025, 7)), {'age': 30, 'bonus': 15, 'education': 15, 'experience': 0, 'language': 20, 'total': 80}),
]


def main():
    n = len(TESTS)
    failed = 0
    for k, (name, func, args, want) in enumerate(TESTS):
        shown = name + "(" + ", ".join(short(a) for a in args) + ")"
        if func is None:
            failed += 1
            print(f"FAIL test {k + 1}: {name} is not defined (api.py could not import it)")
            continue
        try:
            got = func(*args)
        except Exception as e:
            failed += 1
            print(f"FAIL test {k + 1}: {shown} raised {type(e).__name__}: {e}; expected {short(want)}")
            continue
        if not same(got, want):
            failed += 1
            print(f"FAIL test {k + 1}: {shown}: expected {short(want)}, got {short(got)}")
    print(f"{n - failed}/{n} tests passed")
    if failed:
        raise SystemExit(1)


main()

