"""Weights as a number and a unit, converted to milligrams."""
from fractions import Fraction
MG_PER_UNIT = {'g': Fraction(1000), 'ozt': Fraction('31103.4768')}
MG_PER_UNIT['dwt'] = Fraction('1555.17384')
MG_PER_UNIT['ct'] = Fraction(200)
UNIT_ORDER = ['ozt', 'dwt', 'ct', 'g']

def split_amount(text):
    """Split a weight written with its unit, such as "12.5g", "0.8ozt", "7dwt" or "0.75ct", into its parts.

    Returns a tuple (number, unit) of strs: the unit is the suffix "g", "ozt", "dwt" or "ct", the number the text
    before it ("12.5g" gives ("12.5", "g")).

    Valid inputs: text is digits, optionally "." and 1 to 3 digits, then one of the four units, with no spaces.
    """
    for unit in UNIT_ORDER:
        if text.endswith(unit):
            return (text[:-len(unit)], unit)
    return (text, 'g')

def to_milligrams(number, unit):
    """Convert `number` of `unit` to milligrams.

    The units are "g" (1000 mg), "ozt" (troy ounce, 31103.4768 mg), "dwt" (pennyweight, 1555.17384 mg) and "ct"
    (carat, 200 mg). The number is exact; the result is rounded to the nearest milligram, a half rounded up.

    Returns an int.

    Valid inputs: number is a str of digits, optionally "." and 1 to 3 digits, at most 1000; unit is one of the
    four units.
    """
    exact = Fraction(number) * MG_PER_UNIT[unit]
    return int(exact + Fraction(1, 2))

