files.units.py:
"""Kitchen units: their names, what they measure, and their size.

Volumes are measured in millilitres with the usual kitchen sizes (teaspoon 5 ml, tablespoon 15 ml, fluid ounce
30 ml, cup 240 ml, pint 480 ml, quart 960 ml, litre 1000 ml); masses in grams (ounce 28.35 g, pound 16 ounces,
kilogram 1000 g). Anything else is counted in pieces ("each").
"""
VOLUME_ML = {'tsp': 5, 'tbsp': 15, 'floz': 30, 'cup': 240, 'pint': 480, 'quart': 960, 'ml': 1, 'l': 1000}
MASS_G = {'g': (1, 1), 'kg': (1000, 1), 'oz': (567, 20), 'lb': (2268, 5)}
ALIASES = {'teaspoon': 'tsp', 'teaspoons': 'tsp', 'tsps': 'tsp', 'tablespoon': 'tbsp', 'tablespoons': 'tbsp'}
ALIASES.update({'tbsps': 'tbsp', 'tbs': 'tbsp', 'cups': 'cup', 'c': 'cup', 'pints': 'pint', 'pt': 'pint'})
ALIASES.update({'quarts': 'quart', 'qt': 'quart', 'millilitre': 'ml', 'millilitres': 'ml', 'litre': 'l'})
ALIASES.update({'litres': 'l', 'gram': 'g', 'grams': 'g', 'kilogram': 'kg', 'kilograms': 'kg', 'ounce': 'oz'})
ALIASES.update({'ounces': 'oz', 'pound': 'lb', 'pounds': 'lb', 'lbs': 'lb', 'fl oz': 'floz'})

def lookup_unit(word):
    """Everything about the unit written `word`: its standard name, what it measures and its size.

    The capital "T" alone means tablespoon and a lowercase "t" alone teaspoon (the cook's shorthand). Otherwise
    the word is lowercased and a final "." dropped ("Tbsp." -> "tbsp"); the standard names (the keys of VOLUME_ML
    and MASS_G: tsp, tbsp, floz, cup, pint, quart, ml, l, g, kg, oz, lb) stand for themselves, and the names in
    ALIASES (plurals and spelled-out names such as "cups", "teaspoons", "pounds", "fl oz") stand for their unit.

    Returns a dict {"unit": the standard name (str), "kind": "volume" for the units of VOLUME_ML or "mass" for
    those of MASS_G, "size": the size of one unit as a (numerator, denominator) tuple in lowest terms, in
    millilitres for volume and grams for mass ((240, 1) for "cup", (567, 20) for "oz")}, or None when the word is
    not a unit (then the thing is counted in pieces, "each", and "each" itself also gives None).

    Valid inputs: word is a non-empty str.
    """
    if word == 'T':
        name = 'tbsp'
    elif word == 't':
        name = 'tsp'
    else:
        name = word.lower()
        if name.endswith('.'):
            name = name[:-1]
        name = ALIASES.get(name, name)
    if name in VOLUME_ML:
        return {'unit': name, 'kind': 'volume', 'size': (VOLUME_ML[name], 1)}
    if name in MASS_G:
        return {'unit': name, 'kind': 'mass', 'size': MASS_G[name]}
    return None

