"""The life cycle of a sample: which actions are allowed in which state."""
TRANSITIONS = {'new': {'receive': 'received'}}
TRANSITIONS['received'] = {'store': 'stored', 'dispose': 'disposed'}
TRANSITIONS['stored'] = {'checkout': 'out', 'dispose': 'disposed'}
TRANSITIONS['out'] = {'return': 'stored', 'consume': 'consumed'}

def next_state(state, action):
    """The state after `action` in `state`, or None when the action is not allowed there.

    Allowed: new --receive--> received; received --store--> stored; received --dispose--> disposed;
    stored --checkout--> out; stored --dispose--> disposed; out --return--> stored; out --consume--> consumed.
    Nothing is allowed in disposed or consumed.

    Returns a str or None.

    Valid inputs: state and action are non-empty lower-case strs.
    """
    allowed = TRANSITIONS.get(state, {})
    return allowed.get(action)

def valid_events(events):
    """The events that follow the life cycle, replayed in list order.

    Every code starts in state "new". An event is accepted when next_state(current state of its code, action) is
    not None; the code then moves to that state. A rejected event changes nothing.

    Returns a dict {"accepted": list, "rejected": list}: the accepted and the rejected event dicts, each list in the
    order of `events`.

    Valid inputs: events is a list of dicts as events.load_events returns.
    """
    state = {}
    accepted = []
    rejected = []
    for event in events:
        new = next_state(state.get(event['code'], 'new'), event['action'])
        if new is None:
            rejected.append(event)
        else:
            state[event['code']] = new
            accepted.append(event)
    return {'accepted': accepted, 'rejected': rejected}

def final_states(events):
    """The state of every code after replaying the accepted events (see valid_events).

    Codes that have no accepted event are left out (they are still "new").

    Returns a dict {code: state}.

    Valid inputs: as valid_events.
    """
    state = {}
    for event in valid_events(events)['accepted']:
        state[event['code']] = next_state(state.get(event['code'], 'new'), event['action'])
    return state

