files.events.py:
"""Reading the event log the machines write: one line per button press or coin insertion."""
import re
from clock import parse_clock
from machines import WASH_CYCLES, machine_kind
ACTIONS = ('start', 'coins', 'open')
MAX_QUARTERS = 8

def event_problem(line):
    """Why an event line is not a usable event, or None when it is.

    A line is fields separated by one or more spaces: "HH:MM MACHINE ACTION [ARGUMENT]". The machine id is read in
    upper case and the action in lower case. The checks, in this order, the first failing one giving the answer:
    "fields" when there are fewer than 3 fields;
    "time" when the first field is not a clock time "HH:MM" (two digits 00-23, ":", two digits 00-59);
    "machine" when the upper-cased id is not a machine (machines.machine_kind is None);
    "action" when the action is not one of "start", "coins", "open";
    "fields" when the field count is wrong for the action: 3 for "open", 4 for "start" and "coins";
    "kind" when "start" is used on a dryer or "coins" on a washer ("open" is fine on both);
    "cycle" when the lower-cased argument of "start" is not a wash cycle ("normal", "heavy", "delicate");
    "quarters" when the argument of "coins" is not made only of ASCII digits, or its value is below 1 or above
    MAX_QUARTERS (8).

    Returns a str or None.

    Valid inputs: line is a str of 0 to 40 printable ASCII characters.
    """
    fields = line.split()
    if len(fields) < 3:
        return 'fields'
    if not re.fullmatch('([01][0-9]|2[0-3]):[0-5][0-9]', fields[0]):
        return 'time'
    kind = machine_kind(fields[1].upper())
    if kind is None:
        return 'machine'
    action = fields[2].lower()
    if action not in ACTIONS:
        return 'action'
    if len(fields) != (3 if action == 'open' else 4):
        return 'fields'
    if action == 'start' and kind == 'dryer' or (action == 'coins' and kind == 'washer'):
        return 'kind'
    if action == 'start' and fields[3].lower() not in WASH_CYCLES:
        return 'cycle'
    if action == 'coins':
        if not fields[3].isdigit() or not 1 <= int(fields[3]) <= MAX_QUARTERS:
            return 'quarters'
    return None

def parse_event(line):
    """Read a usable event line (see event_problem) into an event record.

    Returns a dict with keys "minute" (the clock time as minutes after midnight, an int), "machine" (the id in upper
    case), "action" (in lower case), "cycle" (the cycle name in lower case for "start", else None) and "quarters"
    (the number of quarters as an int for "coins", else None).

    Valid inputs: line is a str for which event_problem is None.
    """
    fields = line.split()
    action = fields[2].lower()
    event = {'minute': parse_clock(fields[0]), 'machine': fields[1].upper(), 'action': action}
    event['cycle'] = None
    event['quarters'] = None
    if action == 'start':
        event['cycle'] = fields[3].lower()
    elif action == 'coins':
        event['quarters'] = int(fields[3])
    return event

