"""The client lawn list: one line per lawn."""
from calendar_days import is_date_text
GRASS_DAYS = {'fescue': 7, 'rye': 6, 'bermuda': 5, 'zoysia': 10}
SLOPES = ('flat', 'hilly')
MIN_AREA, MAX_AREA = (20, 5000)
MAX_EDGE = 1000

def lawn_problem(line):
    """Why a lawn line is not usable, or None when it is.

    A lawn line is six fields separated by ";": client; area in square metres; grass; edging length in metres;
    slope; date last mowed "YYYY-MM-DD". Each field is read with surrounding spaces stripped, and grass and slope in
    lower case. The checks, in this order, the first failing one giving the answer:
    "fields" when there are not exactly six fields;
    "client" when the client is empty;
    "area" when the area is not made only of ASCII digits or is outside MIN_AREA..MAX_AREA (20 to 5000, inclusive);
    "grass" when the grass is not one of "fescue", "rye", "bermuda", "zoysia";
    "edge" when the edging length is not made only of ASCII digits or is above MAX_EDGE (1000); 0 is fine;
    "slope" when the slope is not "flat" or "hilly";
    "date" when the date is not a real date (calendar_days.is_date_text is False).

    Returns a str or None.

    Valid inputs: line is a str of 0 to 80 printable ASCII characters.
    """
    fields = [field.strip() for field in line.split(';')]
    if len(fields) != 6:
        return 'fields'
    client, area, grass, edge, slope, last = fields
    if client == '':
        return 'client'
    if not area.isdigit() or not MIN_AREA <= int(area) <= MAX_AREA:
        return 'area'
    if grass.lower() not in GRASS_DAYS:
        return 'grass'
    if not edge.isdigit() or int(edge) > MAX_EDGE:
        return 'edge'
    if slope.lower() not in SLOPES:
        return 'slope'
    if not is_date_text(last):
        return 'date'
    return None

def parse_lawn(line):
    """Read a usable lawn line (see lawn_problem).

    Returns a dict with keys "client" (str, stripped), "area" (int square metres), "grass" (str, lower case),
    "edge" (int metres), "slope" (str "flat" or "hilly", lower case) and "last" (the "YYYY-MM-DD" date, stripped).

    Valid inputs: line is a str for which lawn_problem is None.
    """
    client, area, grass, edge, slope, last = [field.strip() for field in line.split(';')]
    lawn = {'client': client, 'area': int(area), 'grass': grass.lower(), 'edge': int(edge)}
    lawn['slope'] = slope.lower()
    lawn['last'] = last
    return lawn

