    "Dn spill COUNT": COUNT cups of lemonade were spilled.
    The checks, in this order, the first failing one giving the answer:
    "fields" when there are fewer than 2 fields;
    "day" when the first field is not a day "D1" to "D30";
    "kind" when the kind is not "buy", "sell", "tip" or "spill";
    "fields" when the field count is not 5 for buy, 4 for sell, 3 for tip and spill;
    "item" when the lower-cased item of a buy is not "lemons", "sugar" or "cups";
    "count" when the count is not a count as count_ok says, with most 500 for buy, 200 for sell, 8 for spill;
    "money" when the amount of buy or tip, or the price of sell, is not money as money.is_money says.

    Returns a str or None.

    Valid inputs: line is a str of 0 to 40 printable ASCII characters.
    """
    fields = line.split()
    if len(fields) < 2:
        return 'fields'
    if not re.fullmatch('D([1-9]|[12][0-9]|30)', fields[0]):
        return 'day'
    kind = fields[1].lower()
    if kind not in FIELD_COUNTS:
        return 'kind'
    if len(fields) != FIELD_COUNTS[kind]:
        return 'fields'
    if kind == 'buy' and fields[2].lower() not in ITEMS:
        return 'item'
    if kind == 'buy' and (not count_ok(fields[3], MAX_BUY)):
        return 'count'
    if kind == 'sell' and (not count_ok(fields[2], MAX_SELL)):
        return 'count'
    if kind == 'spill' and (not count_ok(fields[2], MAX_SPILL)):
        return 'count'
    if kind != 'spill' and (not is_money(fields[-1])):
        return 'money'
    return None

def money_cents(text):
    """The number of cents in a money amount (money.is_money), dollars counting 100 cents each.

    Returns an int.

    Valid inputs: text is a str for which money.is_money is True.
    """
    amount = parse_money(text)
    return amount['dollars'] * 100 + amount['cents']

def parse_entry(line):
    """Read a usable ledger line (see entry_problem).

    Returns a tuple (day, kind, item, count, cents): day is the day number (an int, 7 for "D7"); kind is in lower
    case; item is the lower-cased item for a buy and None otherwise; count is the int count for buy, sell and spill
    and None for a tip; cents is the amount in cents for buy (the whole purchase) and tip, the price of one cup for
    sell, and None for spill.

    Valid inputs: line is a str for which entry_problem is None.
    """
    fields = line.split()
    kind = fields[1].lower()
    day = int(fields[0][1:])
    if kind == 'buy':
        return (day, kind, fields[2].lower(), int(fields[3]), money_cents(fields[4]))
    if kind == 'sell':
        return (day, kind, None, int(fields[2]), money_cents(fields[3]))
    if kind == 'tip':
        return (day, kind, None, None, money_cents(fields[2]))
    return (day, kind, None, int(fields[2]), None)

