"""Reading a light characteristic as printed on a chart, such as "Fl(2) W 10s" or "Oc R 6s"."""
import re
KINDS = ('F', 'Fl', 'LFl', 'Oc', 'Iso', 'Q')
COLORS = ('W', 'R', 'G', 'Y')
SHOW_TENTHS = {'Fl': 5, 'LFl': 20, 'Q': 3, 'Oc': 10}
GAP_TENTHS = {'Fl': 10, 'LFl': 10, 'Q': 7, 'Oc': 10}

def shortest_period(kind, group):
    """The shortest period, in tenths of a second, that fits the pattern of `kind` with `group` signals.

    A signal shows for Fl 5, LFl 20, Q 3, Oc 10 tenths (for Oc the signal is an eclipse); signals are separated by a
    gap of Fl 10, LFl 10, Q 7, Oc 10 tenths, and after the last signal at least one more gap must fit before the
    period ends. So the shortest period is group * signal + group * gap. F and Iso fit any period: 1.

    Returns an int.

    Valid inputs: kind is one of "F", "Fl", "LFl", "Oc", "Iso", "Q"; group is an int from 1 to 9.
    """
    if kind not in SHOW_TENTHS:
        return 1
    return group * SHOW_TENTHS[kind] + group * GAP_TENTHS[kind]

def light_problem(text):
    """Why `text` is not a light characteristic, or None when it is.

    A characteristic is two or three words separated by spaces: KIND, COLOR and PERIOD. KIND is one of F (fixed),
    Fl (flashing), LFl (long flashing), Oc (occulting), Iso (isophase) and Q (quick), optionally followed by a group
    count in brackets with one digit, as "Fl(3)". COLOR is W, R, G or Y. PERIOD is seconds with at most one decimal
    and an "s": one or two digits, optionally "." and one digit, then "s" ("10s", "2.5s"). The checks, in this
    order, the first failing one giving the answer:
    "format" when there are not two or three words;
    "kind" when the first word is not a kind with an optional "(digit)" group;
    "group" when the group is 0, or a group is given for F or Iso;
    "color" when the second word is not a color;
    "format" when F has a third word, or another kind has none;
    "period" when the period is not written as above, or is below 1 or above 30 seconds, or is shorter than
    shortest_period of the kind and group (group 1 when none is given).

    Returns a str or None.

    Valid inputs: text is a str of 0 to 30 printable ASCII characters.
    """
    words = text.split()
    if len(words) not in (2, 3):
        return 'format'
    found = re.fullmatch('(F|Fl|LFl|Oc|Iso|Q)(\\(([0-9])\\))?', words[0])
    if found is None:
        return 'kind'
    kind = found.group(1)
    group = 1 if found.group(3) is None else int(found.group(3))
    if group == 0 or (found.group(2) is not None and kind in ('F', 'Iso')):
        return 'group'
    if words[1] not in COLORS:
        return 'color'
    if (kind == 'F') != (len(words) == 2):
        return 'format'
    if kind == 'F':
        return None
    if not re.fullmatch('[0-9]{1,2}(\\.[0-9])?s', words[2]):
        return 'period'
    tenths = round(float(words[2][:-1]) * 10)
    if tenths < 10 or tenths > 300 or tenths < shortest_period(kind, group):
        return 'period'
    return None

def parse_light(text):
    """Read a characteristic (see light_problem).

    Returns a tuple (kind, group, color, period): kind and color as written; group the int group count (1 when none
    is given); period the int number of tenths of a second ("2.5s" is 25). A fixed light F has no period on the
    chart and gets a period of 10.

    Valid inputs: text is a str for which light_problem is None.
    """
    words = text.split()
    kind, _, rest = words[0].partition('(')
    group = int(rest[0]) if rest else 1
    if kind == 'F':
        return (kind, group, words[1], 10)
    seconds, _, tenth = words[2][:-1].partition('.')
    period = int(seconds) * 10 + (int(tenth) if tenth else 0)
    return (kind, group, words[1], period)

