files.zipcodes.py:
"""ZIP codes: five digits, optionally followed by "-" and four more digits (ZIP+4)."""

def zip_problem(text):
    """Why a typed ZIP code cannot be used, or None when it can.

    The text is stripped of surrounding spaces first. The checks, in this order: "empty" when nothing is left;
    "format" unless it is 5 characters, or 10 characters with "-" as the sixth; "digits" when any character other
    than that "-" is not a digit 0-9; "zero" when the first five digits are "00000".

    Returns a str or None.

    Valid inputs: text is a str of 0 to 14 characters.
    """
    text = text.strip()
    if not text:
        return 'empty'
    if len(text) != 5 and (not (len(text) == 10 and text[5] == '-')):
        return 'format'
    digits = text[:5] + text[6:]
    for ch in digits:
        if ch not in '0123456789':
            return 'digits'
    if text[:5] == '00000':
        return 'zero'
    return None

def parse_zip(text):
    """Split a typed ZIP code into its five-digit ZIP and its four-digit add-on.

    Returns a tuple (zip5, plus4) of strs, with plus4 "" when the code has no add-on.

    Valid inputs: text is a str for which zip_problem is None.
    """
    text = text.strip()
    return (text[:5], text[6:])

def split_digits(digits):
    """Split the digits read from a barcode into the five-digit ZIP and the four-digit add-on.

    5 digits are a ZIP alone; 9 digits are ZIP+4; 11 digits are ZIP+4 followed by a two-digit delivery point,
    which is dropped.

    Returns a tuple (zip5, plus4) of strs, with plus4 "" for 5 digits.

    Valid inputs: digits is a str of 5, 9 or 11 digits.
    """
    return (digits[:5], digits[5:9])

