"""One meeting's minutes as a record."""
from items import parse_attendees, parse_header, parse_item

def parse_meeting(lines):
    """Read the minutes of one meeting.

    The first line starting with "# " is the header (date and title); the first line starting with "attendees:"
    (any case) lists the attendees; every other line is read as an item, and lines that are not items are dropped.

    Returns a dict {"date": str, "title": str, "attendees": sorted list of names, "items": list of item tuples in
    line order}; attendees is [] when there is no attendees line.

    Valid inputs: lines is a list of 1 to 20 strings with exactly one header line; item lines as items.parse_item
    accepts.
    """
    meeting = {'date': None, 'title': '', 'attendees': [], 'items': []}
    has_people = False
    for line in lines:
        if line.startswith('# ') and meeting['date'] is None:
            meeting['date'], meeting['title'] = parse_header(line)
        elif line.lower().startswith('attendees:') and (not has_people):
            meeting['attendees'] = parse_attendees(line)
            has_people = True
        else:
            item = parse_item(line)
            if item is not None:
                meeting['items'].append(item)
    return meeting

def action_number(action_id):
    """The number of an action id: "A12" is 12.

    Returns an int.

    Valid inputs: action_id is "A" followed by the digits of a positive int.
    """
    return int(action_id[1:])

