files.grid.py:
"""Distances on the street grid. A point is a dict {"x": int, "y": int}, in blocks."""

def street_distance(a, b):
    """The walking distance between two points along the streets: |a["x"] - b["x"]| + |a["y"] - b["y"]| blocks.

    Returns an int.

    Valid inputs: a and b are point dicts {"x": int, "y": int}.
    """
    return abs(a['x'] - b['x']) + abs(a['y'] - b['y'])

def closest(point, places):
    """The place nearest to `point` by street distance; ties go to the name that sorts first.

    Returns the str name of that place, or None when places is empty.

    Valid inputs: point is a point dict; places is a dict {name: point dict}.
    """
    best = None
    for name in places:
        key = (street_distance(point, places[name]), name)
        if best is None or key < best:
            best = key
    if best is None:
        return None
    return best[1]

