files.events.py:
"""Reading the event log of one play session.

An event line is "H:MM verb ...": the time since the session started (hours 0 to 99, then two digits of minutes),
then one of these verbs, words separated by runs of whitespace:

- "play L win S": the player played level L and won it with S stars (1 to 3);
- "play L lose": the player played level L and lost;
- "refill": the player asked to buy a full energy refill with gems;
- "ad": the player asked to watch an ad for energy;
- "gift N": a friend sent N energy;
- "buy N": the player bought N gems.
"""

def session_minute(text):
    """The minutes since the start of the session of a time "H:MM" (hours may be 0 to 99).

    Returns an int: hours * 60 + minutes.

    Valid inputs: text is 1 or 2 digits, ":", and exactly two digits from 00 to 59.
    """
    hours, minutes = text.split(':')
    return int(hours) * 60 + int(minutes)

def parse_event(line):
    """Parse one event line (see the module docstring).

    "level" is L for play events and None otherwise; "stars" is S for a won play and 0 otherwise; "amount" is N for
    gift and buy events and 0 otherwise.

    Returns a dict {"minute": int, "verb": str, "level": int or None, "stars": int, "amount": int}.

    Valid inputs: line is an event line as in the module docstring, with L from 1 to 100 and N from 1 to 500.
    """
    words = line.split()
    event = {'minute': session_minute(words[0]), 'verb': words[1], 'level': None, 'stars': 0, 'amount': 0}
    if words[1] == 'play':
        event['level'] = int(words[2])
        if words[3] == 'win':
            event['stars'] = int(words[4])
    elif words[1] in ('gift', 'buy'):
        event['amount'] = int(words[2])
    return event

