"""Rescue teams and which incidents they can take."""
SKILLS_NEEDED = {'avalanche': ['medic', 'probe'], 'fall': ['rope'], 'injury': ['medic']}
SKILLS_NEEDED.update({'lost': [], 'exhaustion': []})
MIN_SIZE = {'avalanche': 4, 'fall': 4, 'injury': 2, 'lost': 3, 'exhaustion': 2}
MAX_REQUIRED = 6

def parse_team(line):
    """Parse a team "<name> <row>,<col> size<N> <skills>".

    The four tokens are separated by one or more spaces. skills is "-" for none, or skill names joined by "+"
    (lowercased, duplicates counted once).

    Returns a dict {"name": str, "cell": (row, col), "size": int, "skills": sorted list of str}.

    Valid inputs: line as described; row and col ints from 0 to 11; N from 1 to 12; skill names of letters.
    """
    name, cell, size, skills = line.split()
    row, col = cell.split(',')
    names = [] if skills == '-' else sorted({s.lower() for s in skills.split('+')})
    return {'name': name, 'cell': (int(row), int(col)), 'size': int(size[4:]), 'skills': names}

def required_size(incident):
    """How many rescuers an incident needs: the larger of MIN_SIZE for its kind (avalanche 4, fall 4, injury 2,
    lost 3, exhaustion 2) and people + 1, but at most MAX_REQUIRED (6).

    Returns an int.

    Valid inputs: incident is a dict as incidents.parse_incident returns.
    """
    return min(max(MIN_SIZE[incident['kind']], incident['people'] + 1), MAX_REQUIRED)

def can_handle(team, incident):
    """Can `team` take `incident`? Only when it has every skill SKILLS_NEEDED lists for the kind (avalanche: medic
    and probe; fall: rope; injury: medic; lost and exhaustion: none) and its size is at least required_size.

    Returns a bool.

    Valid inputs: team as parse_team returns; incident as incidents.parse_incident returns.
    """
    for skill in SKILLS_NEEDED[incident['kind']]:
        if skill not in team['skills']:
            return False
    return team['size'] >= required_size(incident)

