"""Chart movements: how each track moved since the week before."""
from sales_log import track_key
from weekly_chart import chart_for_week

def position_map(lines, week, size):
    """Where each track stands in the chart of `week` (the week's chart of at most `size` tracks).

    Returns a dict {track key (sales_log.track_key of its artist and title): position}; {} for week 0 or a week
    with no chart entries.

    Valid inputs: lines is a list of log lines as sales_log.parse_entry accepts; week is an int from 0 to 30; size
    is an int from 1 to 20.
    """
    if week < 1:
        return {}
    positions = {}
    for row in chart_for_week(lines, {'week': week, 'size': size}):
        positions[track_key(row['artist'], row['title'])] = row['position']
    return positions

def move_label(position, previous, charted_before):
    """The movement label of a track now at `position`.

    previous is its position the week before, or None when it was not in that chart. With a previous position the
    label is "+N" when it climbed N places (previous > position), "-N" when it fell N places, and "=" when it
    stayed. Without one it is "RE" (a re-entry) when charted_before is True, else "NEW".

    Returns a str.

    Valid inputs: position is an int from 1 to 20; previous is None or an int from 1 to 20; charted_before is a
    bool.
    """
    if previous is None:
        return 'RE' if charted_before else 'NEW'
    if previous > position:
        return '+' + str(previous - position)
    if previous < position:
        return '-' + str(position - previous)
    return '='

def movements(lines, week, size):
    """The movement of every track in the chart of `week` (charts have at most `size` tracks; weeks count from 1).

    For each track, in position order: its position the week before (week - 1), and whether it was in any chart of
    weeks 1 to week - 2, give its move_label.

    Returns a list of (position, label) tuples in position order.

    Valid inputs: as position_map, with week from 1 to 30.
    """
    previous = position_map(lines, week - 1, size)
    earlier = {}
    for old_week in range(1, week - 1):
        earlier.update(position_map(lines, old_week, size))
    out = []
    for position, artist, title, units in chart_for_week(lines, week, size):
        key = track_key(artist, title)
        out.append((position, move_label(position, previous.get(key), key in earlier)))
    return out

