"""How serious a violation is and what it is fined."""
BASE_FINES = {'minor': 10000, 'major': 25000, 'severe': 50000}
MAX_FINE = 200000

def band(excess):
    """The severity band of a reading that is `excess` dB over the limit: "none" for 0, "minor" for 1 to 5,
    "major" for 6 to 15, "severe" for 16 or more.

    Returns a str.

    Valid inputs: excess is an int from 0 to 110.
    """
    if excess <= 0:
        return 'none'
    if excess <= 5:
        return 'minor'
    if excess <= 15:
        return 'major'
    return 'severe'

def fine_cents(fine_number, excess):
    """The fine in cents for the fine_number-th fine on one ticket, for a reading `excess` dB over the limit.

    The base fine of the band (BASE_FINES: minor 10000, major 25000, severe 50000) doubles with every earlier fine
    on the ticket (base * 2 ** (fine_number - 1)) and is capped at MAX_FINE (200000).

    Returns an int.

    Valid inputs: fine_number is an int from 1 to 20; excess is an int from 1 to 110.
    """
    amount = BASE_FINES[band(excess)]
    for _ in range(fine_number - 1):
        amount *= 2
        if amount >= MAX_FINE:
            return MAX_FINE
    return min(amount, MAX_FINE)

