    ('doses_due', doses_due, ('B01;Insulin;07:00;6', '19:00', 12), ['19:00', '01:00']),
    ('missed_doses', missed_doses, (['B03; Insulin;23:00 ;24', 'B01;Heparin;08:00 ;8', 'B02;Furosemide;20:00 ;6', 'B03; Furosemide;14:30 ;4'], ['B02;Furosemide;01:30', 'B01;Heparin;23:00', 'B03;Furosemide;21:30'], '19:00', 8, '01:41'), [('B02', 'Furosemide', '20:00'), ('B03', 'Insulin', '23:00')]),
    ('missed_doses', missed_doses, (['B01;Heparin;19:00;4'], [], '19:00', 12, '20:00'), []),
]


def main():
    n = len(TESTS)
    failed = 0
    for k, (name, func, args, want) in enumerate(TESTS):
        shown = name + "(" + ", ".join(short(a) for a in args) + ")"
        if func is None:
            failed += 1
            print(f"FAIL test {k + 1}: {name} is not defined (api.py could not import it)")
