    "oversize": length <= 2700, length plus girth <= 4190 and weight <= 68000;
    otherwise "rejected".

    Returns a str.

    Valid inputs: parcel is a dict as dimensions.parse_parcel returns.
    """
    length, width, height = parcel['dims']
    grams = parcel['grams']
    if length <= 353 and width <= 250 and (height <= 25) and (grams <= 500):
        return 'letter'
    around = length_plus_girth(length, width, height)
    if length <= 600 and around <= 1500 and (grams <= 5000):
        return 'small'
    if length <= 1200 and around <= 3000 and (grams <= 30000):
        return 'standard'
    if length <= 2700 and around <= 4190 and (grams <= 68000):
        return 'oversize'
    return 'rejected'

def surcharges(parcel):
    """The handling surcharges of a parcel, in cents (SURCHARGE_CENTS).

    "LONG" (1200) when the longest side is over LONG_MM (1000) mm; "HEAVY" (2000) when the actual weight is over
    HEAVY_GRAMS (25000) g; "BULKY" (1500) when the volume in cm3, rounded up to a whole number, is over BULKY_CM3
    (100000); "REMOTE" (800) when the zone is REMOTE_ZONE (8).

    Returns a list of (code, cents) tuples sorted by code ([] when none applies).

    Valid inputs: parcel is a dict as dimensions.parse_parcel returns.
    """
    codes = []
    if parcel['dims'][0] > LONG_MM:
        codes.append('LONG')
    if parcel['grams'] > HEAVY_GRAMS:
        codes.append('HEAVY')
    if volume_cm3(*parcel['dims']) > BULKY_CM3:
        codes.append('BULKY')
    if parcel['zone'] == REMOTE_ZONE:
        codes.append('REMOTE')
    return [(code, SURCHARGE_CENTS[code]) for code in sorted(codes)]

