"""Character classes of a password (printable ASCII characters only)."""
POOLS = {'lower': 26, 'upper': 26, 'digit': 10, 'symbol': 33}
CLASS_ORDER = ['lower', 'upper', 'digit', 'symbol']

def char_class(ch):
    """The class of one character: "lower" for a-z, "upper" for A-Z, "digit" for 0-9, else "symbol".

    Returns a str.

    Valid inputs: ch is one printable ASCII character (space included).
    """
    if 'a' <= ch <= 'z':
        return 'lower'
    if 'A' <= ch <= 'Z':
        return 'upper'
    if '0' <= ch <= '9':
        return 'digit'
    return 'symbol'

def class_counts(password):
    """How many characters of each class the password has.

    Returns a dict {"lower": int, "upper": int, "digit": int, "symbol": int} with all four keys (0 when absent).

    Valid inputs: password is a str of 0 to 40 printable ASCII characters.
    """
    counts = {name: 0 for name in CLASS_ORDER}
    for ch in password:
        counts[char_class(ch)] += 1
    return counts

def pool_size(password):
    """The size of the alphabet a guesser must try: the sum of POOLS (lower 26, upper 26, digit 10, symbol 33) over
    the classes that occur in the password.

    Returns an int (0 for the empty password).

    Valid inputs: as class_counts.
    """
    counts = class_counts(password)
    total = 0
    for name in CLASS_ORDER:
        if counts[name] > 0:
            total += POOLS[name]
    return total

