files.sig_codes.py:
"""Reading the directions ("sig") on a prescription: how many units the patient takes a day."""
from fractions import Fraction
FIXED = {'QD': 1, 'DAILY': 1, 'QHS': 1, 'BID': 2, 'TID': 3, 'QID': 4}
FORMS = {'tab': 'tab', 'tabs': 'tab', 'cap': 'cap', 'caps': 'cap'}
FORMS.update({'ml': 'ml', 'puff': 'puff', 'puffs': 'puff'})

def dose_amount(text):
    """Read the amount of one dose: a whole number ("2"), a fraction ("1/2") or a decimal ("1.5", "0.25").

    Returns a tuple (numerator, denominator) of ints in lowest terms with denominator >= 1.

    Valid inputs: text is a str of digits, digits "/" digits (denominator not 0), or digits "." digits; the value is
    above 0 and at most 20.
    """
    value = Fraction(text)
    return (value.numerator, value.denominator)

def times_per_day(code):
    """How many doses a day a frequency code means, in any case.

    QD, DAILY and QHS: 1; BID: 2; TID: 3; QID: 4; QOD (every other day): 1/2; QW (once a week): 1/7; QnH (every n
    hours, e.g. Q8H): 24/n.

    Returns a tuple (numerator, denominator) in lowest terms.

    Valid inputs: code is one of the codes above, in any case; for QnH, n is an int from 1 to 24.
    """
    code = code.upper()
    if code in FIXED:
        return (FIXED[code], 1)
    if code == 'QOD':
        return (1, 2)
    if code == 'QW':
        return (1, 7)
    value = Fraction(24, int(code[1:-1]))
    return (value.numerator, value.denominator)

def read_sig(sig):
    """Read a sig "AMOUNT FORM CODE": the dose amount, the doses a day and the units a day it asks for.

    The form word (tab, tabs, cap, caps, ml, puff, puffs, in any case) names the unit; words are separated by
    spaces. The units a day are the dose amount times the doses a day.

    Returns a dict {"dose": (numerator, denominator) of the dose amount, "per_day": (numerator, denominator) of the
    doses a day, "units_per_day": (numerator, denominator) of the units a day, "form": "tab", "cap", "ml" or
    "puff"}, every fraction in lowest terms ("tabs" counts as "tab", "caps" as "cap", "puffs" as "puff").

    Valid inputs: sig is a str of three words: an amount as dose_amount accepts, a form as above and a code as
    times_per_day accepts (spaces around allowed).
    """
    amount, form, code = sig.split()
    dose = dose_amount(amount)
    per_day = times_per_day(code)
    units = Fraction(*dose) * Fraction(*per_day)
    reading = {'dose': dose, 'per_day': per_day, 'units_per_day': (units.numerator, units.denominator)}
    reading['form'] = FORMS[form.lower()]
    return reading

