"""Points for single playfield switches, read from whole (tenths, kind, arg) events."""
BASE_POINTS = {'bumper': 100, 'target': 500, 'orbit': 2000}
SPIN_POINTS = 15
TARGET_LETTERS = 'ABCDE'

def hit_points(event):
    """The points one switch event scores on its own.

    `event` is a whole (tenths, kind, arg) tuple. A "spinner" scores SPIN_POINTS (15) per spin, its arg being the
    number of spins; a "bumper" scores 100, a "target" 500 and an "orbit" 2000; every other kind (ramp, drain,
    tilt, anything unknown) scores 0 here.

    Returns an int.

    Valid inputs: event is a (tenths, kind, arg) tuple with a lower-case kind; arg is a str of digits when kind is
    "spinner", any str otherwise.
    """
    time, kind, arg = event
    if kind == 'spinner':
        return SPIN_POINTS * int(arg)
    return BASE_POINTS.get(kind, 0)

def hit_counts(events):
    """How many events there are of each kind.

    Returns a dict {kind: int count} with an entry only for kinds that occur; look kinds up with .get(kind, 0).

    Valid inputs: events is a list of (tenths, kind, arg) tuples.
    """
    counts = {}
    for event in events:
        counts[event[1]] = counts.get(event[1], 0) + 1
    return counts

def target_index(arg):
    """The drop target an arg names, as its position in the bank: 0 for A, 1 for B, 2 for C, 3 for D, 4 for E (in
    either case); None when the arg names no target.

    Returns an int or None.

    Valid inputs: arg is a str with no spaces.
    """
    letter = arg.upper()
    if len(letter) == 1 and letter in TARGET_LETTERS:
        return TARGET_LETTERS.index(letter)
    return None

