"""Plants and the needs of their species."""
PROFILES = {}
PROFILES['fern'] = {'threshold': 60, 'dry_rate': 12, 'ml_per_litre': 150}
PROFILES['cactus'] = {'threshold': 15, 'dry_rate': 3, 'ml_per_litre': 40}
PROFILES['basil'] = {'threshold': 45, 'dry_rate': 10, 'ml_per_litre': 120}
PROFILES['orchid'] = {'threshold': 35, 'dry_rate': 6, 'ml_per_litre': 80}
PROFILES['ivy'] = {'threshold': 40, 'dry_rate': 7, 'ml_per_litre': 100}
MIN_ML = 50
GARDEN_DEFAULTS = {'shelf': 1, 'outdoor': False, 'moisture': 80}

def species_profile(species):
    """The needs of a species, from PROFILES.

    "threshold" is the soil moisture in percent below which the plant must be watered (fern 60, cactus 15, basil 45,
    orchid 35, ivy 40); "dry_rate" the percentage points of moisture its soil loses per day before heat (fern 12,
    cactus 3, basil 10, orchid 6, ivy 7); "ml_per_litre" the water one watering takes per litre of pot (fern 150,
    cactus 40, basil 120, orchid 80, ivy 100).

    Returns a new dict {"threshold": int, "dry_rate": int, "ml_per_litre": int}.

    Valid inputs: species is a key of PROFILES ("fern", "cactus", "basil", "orchid" or "ivy").
    """
    return dict(PROFILES[species])

def parse_plant(line, defaults):
    """Parse a plant line such as "Fern-1 fern 2.5L shelf=3 outdoor m=70".

    Words are separated by whitespace: the plant's name, its species, and its pot size in litres followed by "L"
    (a whole number or one decimal, stored as tenths of a litre, so "2.5L" -> 25 and "3L" -> 30). Any later words are
    options, in any order: "shelf=N", "outdoor" (the plant is outdoors) and "m=N", the soil moisture in percent at
    the start. An option that is not given takes its value from defaults: defaults["shelf"], defaults["outdoor"]
    and defaults["moisture"]. GARDEN_DEFAULTS holds the garden's usual defaults: shelf 1, indoors (False),
    moisture 80.

    Returns a dict {"name": str, "species": str, "tenths": int, "shelf": int, "outdoor": bool, "moisture": int}.

    Valid inputs: the species is a key of PROFILES; the pot size is 0.1 to 50 litres; shelf N is 1 to 9; m=N has N
    from 0 to 100; each option appears at most once; defaults is a dict {"shelf": int from 1 to 9, "outdoor": bool,
    "moisture": int from 0 to 100}.
    """
    words = line.split()
    size = words[2][:-1]
    if '.' in size:
        whole, frac = size.split('.')
        tenths = int(whole) * 10 + int(frac)
    else:
        tenths = int(size) * 10
    plant = {'name': words[0], 'species': words[1], 'tenths': tenths, 'shelf': defaults['shelf']}
    plant['outdoor'] = defaults['outdoor']
    plant['moisture'] = defaults['moisture']
    for word in words[3:]:
        if word == 'outdoor':
            plant['outdoor'] = True
        elif word.startswith('shelf='):
            plant['shelf'] = int(word[6:])
        elif word.startswith('m='):
            plant['moisture'] = int(word[2:])
    return plant

def water_ml(plant):
    """How much water one watering of a plant takes, in millilitres.

    The raw amount is species_profile(plant["species"])["ml_per_litre"] * plant["tenths"] // 10 (rounded down). It
    is then rounded to the nearest multiple of 10, halves going up ((raw + 5) // 10 * 10), and raised to at least
    MIN_ML (50).

    Returns an int.

    Valid inputs: plant is a dict with at least the keys "species" (a key of PROFILES) and "tenths" (an int from 1
    to 500, the pot size in tenths of a litre), as parse_plant returns; other keys are ignored.
    """
    raw = species_profile(plant['species'])['ml_per_litre'] * plant['tenths'] // 10
    rounded = (raw + 5) // 10 * 10
    return max(rounded, MIN_ML)

