"""Daily pollen counts from the sampler, one day per text line."""
import re
KINDS = ['tree', 'grass', 'weed']
DATE_PATTERN = re.compile('^\\d{4}-(0[1-9]|1[0-2])-(0[1-9]|1\\d|2[0-8])$')

def reading_problem(line):
    """Why a reading line is not valid, or None when it is.

    A line is a date "YYYY-MM-DD" followed by 0 to 3 tokens "kind=count", all separated by one or more spaces
    (spaces around the line are ignored). The checks, in this order, the first failing one giving the answer:
    "date" when the first word is missing or not a date with month 01-12 and day 01-28;
    "token" for the first later word that is not "name=digits" (exactly one "=", at least one digit after it);
    "kind" for the first token whose name is not "tree", "grass" or "weed";
    "repeat" when a kind appears in more than one token.
    Each check looks at the whole line before the next check starts.

    Returns a str or None.

    Valid inputs: line is any string.
    """
    words = line.split()
    if not words or DATE_PATTERN.match(words[0]) is None:
        return 'date'
    tokens = words[1:]
    for token in tokens:
        parts = token.split('=')
        if len(parts) != 2 or not parts[1].isdigit():
            return 'token'
    names = [token.split('=')[0] for token in tokens]
    for name in names:
        if name not in KINDS:
            return 'kind'
    if len(set(names)) < len(names):
        return 'repeat'
    return None

def parse_reading(line):
    """Read one valid reading line into a record; a kind with no token has count 0.

    Returns a dict {"date": str, "tree": int, "grass": int, "weed": int} (grains per cubic meter).

    Valid inputs: line is a string for which reading_problem returns None.
    """
    words = line.split()
    record = {'date': words[0], 'tree': 0, 'grass': 0, 'weed': 0}
    for token in words[1:]:
        name, count = token.split('=')
        record[name] = int(count)
    return record

def history(lines):
    """The valid readings by date, oldest first; for a date read on several valid lines the last line counts.

    Invalid lines (see reading_problem) are skipped.

    Returns a list of dicts as parse_reading returns, sorted by date.

    Valid inputs: lines is a list of 0 to 40 strings.
    """
    by_date = {}
    for line in lines:
        if reading_problem(line) is None:
