"""The public pollen scale: each count classified into a level record, from "none" to "very high"."""
LEVELS = ['none', 'low', 'moderate', 'high', 'very high']
THRESHOLDS = {'tree': [15, 90, 1500], 'grass': [5, 20, 200], 'weed': [10, 50, 500]}

def classify(count, kind):
    """The level of a pollen count of a kind on the public scale.

    A count of 0 is level 0 (none). Otherwise the level is 1 (low), moved up one level for each of the kind's three
    thresholds the count reaches (count >= threshold): tree 15, 90, 1500; grass 5, 20, 200; weed 10, 50, 500
    (grains per cubic meter). The level words are, from 0 to 4: "none", "low", "moderate", "high", "very high".

    Returns a dict {"index": int from 0 to 4, "name": the level word}.

    Valid inputs: count is an int of 0 or more; kind is "tree", "grass" or "weed".
    """
    index = 0
    if count > 0:
        index = 1
        for threshold in THRESHOLDS[kind]:
            if count >= threshold:
                index += 1
    return {'index': index, 'name': LEVELS[index]}

files.weather.py:
"""How the forecast weather of a day pushes pollen counts up or down."""

def parse_weather(text):
    """Read a day's weather "rain=R wind=W temp=T" (tokens in any order, separated by spaces).

    Returns a dict {"rain": int (mm), "wind": int (km/h), "temp": int (degrees C)}; a missing token gives 0.

    Valid inputs: text has 0 to 3 distinct tokens "name=value" with names rain, wind and temp; rain and wind are
    0-200 written in digits, temp is -30 to 45 (a leading "-" for below zero).
    """
    weather = {'rain': 0, 'wind': 0, 'temp': 0}
    for token in text.split():
        name, value = token.split('=')
        weather[name] = int(value)
    return weather

def weather_percent(weather):
    """The percent by which the weather scales the day's pollen count.

    Start at 100 and apply, in this order, each step as percent = percent * factor // 100:
    rain: 10 mm or more factor 20; else 2 mm or more factor 50; else no change;
    wind: 25 km/h or more factor 140; else 15 km/h or more factor 120; else no change;
    temp: below 5 degrees factor 30; else below 12 factor 70; else 25 or more factor 115; else no change.

    Returns an int.

    Valid inputs: weather is a dict as parse_weather returns.
    """
    percent = 100
    if weather['rain'] >= 10:
        percent = percent * 20 // 100
    elif weather['rain'] >= 2:
        percent = percent * 50 // 100
    if weather['wind'] >= 25:
        percent = percent * 140 // 100
    elif weather['wind'] >= 15:
        percent = percent * 120 // 100
    if weather['temp'] < 5:
        percent = percent * 30 // 100
    elif weather['temp'] < 12:
        percent = percent * 70 // 100
    elif weather['temp'] >= 25:
        percent = percent * 115 // 100
    return percent

