"""Postal codes: cleaning, checking and splitting codes written like "AB12 3CD"."""
BANNED_UNIT_LETTERS = 'CIKMOV'
CODE_LENGTH = 7

def normalize_code(text):
    """Clean a postal code as it was typed.

    Every space is removed and every letter is uppercased. When the result has at least 4 characters, one space is
    put before its last 3 characters ("ab123cd" becomes "AB12 3CD", " kt 0 47bx " becomes "KT04 7BX"); a shorter
    result is returned without a space ("ab1" becomes "AB1", "" stays "").

    Returns a str.

    Valid inputs: text is a string of 0 to 12 characters, each an ASCII letter, a digit or a space.
    """
    compact = text.replace(' ', '').upper()
    if len(compact) >= 4:
        return compact[:-3] + ' ' + compact[-3:]
    return compact

def code_problem(text):
    """Why `text` is not a valid postal code, or None when it is.

    The text is cleaned first (spaces removed, letters uppercased, as normalize_code does). The remaining characters
    are then checked, in this order, the first failing check giving the answer:
    "length" unless there are exactly 7 characters;
    "area" unless characters 1 and 2 are both letters;
    "district" unless characters 3 and 4 are both digits and are not "00";
    "sector" unless character 5 is a digit;
    "unit" unless characters 6 and 7 are both letters and neither is one of C, I, K, M, O, V.

    Returns a str or None.

    Valid inputs: as normalize_code.
    """
    compact = normalize_code(text).replace(' ', '')
    if len(compact) != CODE_LENGTH:
        return 'length'
    if not (compact[0].isalpha() and compact[1].isalpha()):
        return 'area'
    district = compact[2:4]
    if not district.isdigit() or district == '00':
        return 'district'
    if not compact[4].isdigit():
        return 'sector'
    for letter in compact[5:]:
        if not letter.isalpha() or letter in BANNED_UNIT_LETTERS:
            return 'unit'
    return None

def split_code(text):
    """The parts of a valid postal code: area (letters 1-2), district (digits 3-4), sector (digit 5), unit (6-7).

    The text is cleaned first as normalize_code does, so "ab12 3cd" gives ("AB", 12, 3, "CD").

    Returns a tuple (area str, district int, sector int, unit str).

    Valid inputs: text is a string as normalize_code accepts, for which code_problem is None.
    """
    compact = normalize_code(text).replace(' ', '')
    return (compact[:2], int(compact[2:4]), int(compact[4]), compact[5:])

