"""The weekly visits timetable of each unit of the prison."""
from visit_clock import clock_minutes, parse_day, weekday_of
UNIT_TABLES = {'A': 12, 'B': 4, 'C': 8}
SLOTS = {}
SLOTS['A'] = {1: [('14:00', '15:30')], 3: [('14:00', '15:30')], 5: [('13:30', '15:00'), ('10:00', '11:30')]}
SLOTS['B'] = {2: [('09:30', '10:30')], 6: [('14:00', '15:00')]}
SLOTS['C'] = {5: [('10:00', '12:00'), ('14:00', '16:00')], 6: [('14:00', '16:00'), ('10:00', '12:00')]}

def slots_on(unit, day):
    """The visiting slots of `unit` on the date `day`, earliest first.

    The timetable repeats every week. Unit A (general, 12 tables): Tuesday and Thursday 14:00-15:30, Saturday
    10:00-11:30 and 13:30-15:00. Unit B (high security, 4 tables): Wednesday 09:30-10:30, Sunday 14:00-15:00. Unit C
    (family unit, 8 tables): Saturday and Sunday 10:00-12:00 and 14:00-16:00. Other days have no slots.

    Returns a list of (start "HH:MM", end "HH:MM") tuples.

    Valid inputs: unit is "A", "B" or "C"; day is a date "YYYY-MM-DD" with year 1900-2100.
    """
    found = SLOTS[unit].get(weekday_of(day), [])
    return sorted(found, key=lambda slot: clock_minutes(slot[0]))

def slot_at(unit, day, time):
    """The slot of `unit` on `day` that starts at the clock time `time`, compared as times of day ("9:30" is the
    09:30 slot).

    Returns a tuple (start "HH:MM", end "HH:MM") as the timetable writes it, or None when no slot starts then.

    Valid inputs: unit and day as slots_on accepts; time is "H:MM" or "HH:MM" with hours 0-23, minutes 00-59.
    """
    wanted = clock_minutes(time)
    for start, end in slots_on(unit, day):
        if clock_minutes(start) == wanted:
            return (start, end)
    return None

def slot_length(start, end):
    """The length of a slot in minutes, from its start time to its end time ("HH:MM" each, end after start).

    Returns an int.

    Valid inputs: start and end are "HH:MM" times on the same day, end later than start.
    """
    return clock_minutes(end) - clock_minutes(start)

