"""Head-to-head comparisons between candidates (a check on the instant-runoff result)."""

def prefers(ranking, a, b):
    """Does `ranking` put a above b?

    A ranked name is above every unranked name. When neither a nor b is ranked, the ballot prefers neither.

    Returns a bool: True when a is ranked and either b is not ranked or a comes earlier than b.

    Valid inputs: ranking is a tuple of distinct str; a and b are different str.
    """
    if a not in ranking:
        return False
    if b not in ranking:
        return True
    return ranking.index(a) < ranking.index(b)

def pairwise_margin(ballots, a, b):
    """The votes that prefer a over b minus the votes that prefer b over a, each ballot weighted by its count.

    Returns an int (negative when b is preferred by more votes; 0 when neither name is ranked on any ballot).

    Valid inputs: ballots as tally.count_round accepts; a and b are different str.
    """
    margin = 0
    for count, ranking in ballots:
        if prefers(ranking, a, b):
            margin += count
        elif prefers(ranking, b, a):
            margin -= count
    return margin

def condorcet_winner(ballots, candidates):
    """The candidate who beats every other candidate head to head, or None.

    A candidate beats another when pairwise_margin(ballots, candidate, other) > 0 (a margin of 0 is not a win). With
    a single candidate, that candidate is the Condorcet winner. At most one candidate can beat all the others.

    Returns a str or None.

    Valid inputs: ballots as tally.count_round accepts; candidates is a list of 1 to 8 distinct names.
    """
    for a in sorted(candidates):
        beats_all = True
        for b in candidates:
            if b != a and pairwise_margin(ballots, a, b) <= 0:
                beats_all = False
                break
        if beats_all:
            return a
    return None

files.tally.py:
"""Counting the votes of one round."""

def top_choice(ranking, active):
    """The most preferred name on `ranking` that is still in `active`.

    Returns a str, or None when no name on the ranking is active (the ballot is exhausted).

    Valid inputs: ranking is a tuple of distinct str (possibly empty); active is a list of distinct str.
    """
    for name in ranking:
        if name in active:
            return name
    return None

def count_round(ballots, active):
    """Count one round: the count of each ballot goes to its top_choice among `active`.

    Returns a tuple (counts, exhausted): counts is a dict {name: votes} with an entry for every name in active (0
    when the name got no votes); exhausted is an int, the total count of the ballots whose top_choice is None.

    Valid inputs: ballots is a list of (count, ranking) tuples as ballots.clean_ballots returns (count an int >= 1,
    ranking a non-empty tuple of distinct str); active is a list of 1 to 8 distinct names.
    """
    counts = {name: 0 for name in active}
    exhausted = 0
    for count, ranking in ballots:
        choice = top_choice(ranking, active)
        if choice is None:
            exhausted += count
        else:
            counts[choice] += count
    return (counts, exhausted)

