    ('percent_share', percent_share, (905174681, '83.85'), 758988970),
    ('gross_commission', gross_commission, (50000001,), 3000000),
    ('gross_commission', gross_commission, (1609600000,), 65884000),
    ('side_amounts', side_amounts, ({'date': '2024-01-01', 'address': '1 Elm St', 'price': 50000000, 'listing': 'ann', 'buyer': 'bob', 'referral': None},), [('ann', 'listing', 1500000, 0), ('bob', 'buyer', 1500000, 0)]),
    ('side_amounts', side_amounts, ({'date': '2024-01-01', 'address': '1 Elm St', 'price': 7777777, 'listing': 'ann', 'buyer': 'ann', 'referral': ('listing', 35)},), [('ann', 'dual', 273000, 147000)]),
]


def main():
    n = len(TESTS)
    failed = 0
    for k, (name, func, args, want) in enumerate(TESTS):
        shown = name + "(" + ", ".join(short(a) for a in args) + ")"
        if func is None:
            failed += 1
            print(f"FAIL test {k + 1}: {name} is not defined (api.py could not import it)")
            continue
        try:
            got = func(*args)
        except Exception as e:
            failed += 1
            print(f"FAIL test {k + 1}: {shown} raised {type(e).__name__}: {e}; expected {short(want)}")
            continue
        if not same(got, want):
            failed += 1
            print(f"FAIL test {k + 1}: {shown}: expected {short(want)}, got {short(got)}")
    print(f"{n - failed}/{n} tests passed")
    if failed:
        raise SystemExit(1)


main()

