"""Course distances and run log lines."""
from clock import parse_clock
MILE_MM = 1609344
NAMED_COURSES = {'half': 21097, 'marathon': 42195}

def course_metres(label):
    """The length of a course in whole metres, from its label.

    The label is first stripped of surrounding spaces and lowercased. Then, the first matching rule wins:
    "half" is 21097 and "marathon" is 42195 (NAMED_COURSES);
    "<N>mi" is N miles: N * 1609344 millimetres (MILE_MM), rounded to the nearest metre with halves up;
    "<X>k" is X kilometres, where X is a whole number or a number with 1 to 3 decimals ("21.1k" is 21100);
    "<N>m" is N metres.

    Returns an int.

    Valid inputs: label is a string that, stripped and lowercased, is "half", "marathon", "<N>mi" or "<N>m" with N
    a whole number from 1 to 99999, or "<X>k" with X a whole number from 0 to 999 optionally followed by "." and
    1 to 3 digits, with the value above 0.
    """
    text = label.strip().lower()
    if text in NAMED_COURSES:
        return NAMED_COURSES[text]
    if text.endswith('mi'):
        return (int(text[:-2]) * MILE_MM + 500) // 1000
    if text.endswith('k'):
        whole, _, frac = text[:-1].partition('.')
        return int(whole) * 1000 + int(frac.ljust(3, '0'))
    return int(text[:-1])

def parse_run(line):
    """Read one run log line "date;runner;course;time".

    Each field is stripped of surrounding spaces. The runner name is lowercased, the course is turned into metres by
    the course-label rules above, and the time into seconds by the clock rules.

    Returns a dict {"date": str (the date text, "YYYY-MM-DD"), "runner": str, "metres": int, "seconds": int}.

    Valid inputs: line is a string with exactly three ";" separators; date is a real calendar date written
    "YYYY-MM-DD"; runner is non-empty letters; course is a valid course label; time is a valid clock text.
    """
    day, runner, course, time = [part.strip() for part in line.split(';')]
    metres = course_metres(course)
    return {'date': day, 'runner': runner.lower(), 'metres': metres, 'seconds': parse_clock(time)}

