files.intervals.py:
"""Sets of times as lists of half-open spans.

A span is a dict {"start": int, "end": int} of minute counts: minute start is in it, minute end is not, so its
length is end - start. A span with end <= start is empty. Every function returns new dicts and leaves its inputs
unchanged.
"""

def merge_intervals(spans):
    """The same set of minutes as a sorted list of disjoint spans.

    Empty spans are dropped; the rest are sorted by start (then end), and a span that overlaps or touches the one
    before it (its start <= the previous end) is joined to it.

    Returns a list of {"start": int, "end": int} dicts, sorted by start, with each end < the next start.

    Valid inputs: spans is a list of 0 to 300 dicts {"start": int, "end": int}.
    """
    ordered = sorted(((sp['start'], sp['end']) for sp in spans if sp['end'] > sp['start']))
    merged = []
    for start, end in ordered:
        if merged and start <= merged[-1]['end']:
            if end > merged[-1]['end']:
                merged[-1]['end'] = end
        else:
            merged.append({'start': start, 'end': end})
    return merged

def intersect_intervals(first, second):
    """The minutes that are in both sets.

    Returns a list of span dicts in merge_intervals form ([] when the sets share no minute).

    Valid inputs: first and second are lists of span dicts as merge_intervals accepts.
    """
    out = []
    for a in merge_intervals(first):
        for b in merge_intervals(second):
            lo = max(a['start'], b['start'])
            hi = min(a['end'], b['end'])
            if lo < hi:
                out.append({'start': lo, 'end': hi})
    return merge_intervals(out)

def subtract_intervals(kept, removed):
    """The minutes of `kept` that are not in `removed`.

    Returns a list of span dicts in merge_intervals form.

    Valid inputs: kept and removed are lists of span dicts as merge_intervals accepts.
    """
    cuts = merge_intervals(removed)
    out = []
    for span in merge_intervals(kept):
        pieces = [(span['start'], span['end'])]
        for cut in cuts:
            rest = []
            for ps, pe in pieces:
                if cut['end'] <= ps or cut['start'] >= pe:
                    rest.append((ps, pe))
                    continue
                if cut['start'] > ps:
                    rest.append((ps, cut['start']))
                if cut['end'] < pe:
                    rest.append((cut['end'], pe))
            pieces = rest
        out.extend(({'start': ps, 'end': pe} for ps, pe in pieces))
    return merge_intervals(out)

def total_minutes(spans):
    """The number of distinct minutes in a set (overlaps counted once), as an int (0 for an empty set).

    Valid inputs: spans is a list of span dicts as merge_intervals accepts.
    """
    return sum((sp['end'] - sp['start'] for sp in merge_intervals(spans)))

