"""Which cells a formula reads, and the order to compute the formula cells in."""
from cells import expand_range, parse_address
from grammar import parse_formula

def references(tree):
    """The cells an expression tree reads: every ref, and every cell of every range. Returns a list of distinct
    plain addresses, sorted by row, then by column (so "B1" comes before "A2").

    Valid inputs: tree is a tree as grammar.parse_formula returns.
    """
    found = set()
    stack = [tree]
    for _ in range(10000):
        if not stack:
            break
        node = stack.pop()
        if node[0] == 'ref':
            found.add(node[1])
        elif node[0] == 'range':
            found.update(expand_range(node[1]))
        elif node[0] == 'neg':
            stack.append(node[1])
        elif node[0] == 'bin':
            stack.extend([node[2], node[3]])
        elif node[0] == 'call':
            stack.extend(node[2])
    return sorted(found, key=address_key)

def address_key(address):
    """Sort key of an address: (row, column), so cells sort row by row (not tested)."""
    spot = parse_address(address)
    return (spot['row'], spot['col'])

def evaluation_order(sheet):
    """The order in which the formula cells of a sheet can be computed.

    A formula cell is one whose content starts with "="; it depends on the formula cells it reads (cells it reads
    that are empty or hold plain values need no computing). A cell is ready when every formula cell it depends on
    has been placed. Repeatedly the ready cell that sorts first (by row, then column) is placed next. Formula cells
    that never become ready (they are in a cycle or depend on one) are left over. Returns a tuple (order, stuck):
    two lists of plain addresses, order in placing order, stuck sorted by row then column.

    Valid inputs: sheet is a dict {plain address: str} of 0 to 60 cells; every formula is well-formed as
    grammar.parse_formula accepts.
    """
    needs = {}
    for address, content in sheet.items():
        if content.startswith('='):
            reads = references(parse_formula(content[1:]))
            needs[address] = [a for a in reads if a in sheet and sheet[a].startswith('=')]
    order = []
    placed = set()
    for _ in range(len(needs)):
        ready = [a for a in needs if a not in placed and all((n in placed for n in needs[a]))]
        if not ready:
            break
        pick = min(ready, key=address_key)
        order.append(pick)
        placed.add(pick)
    stuck = sorted((a for a in needs if a not in placed), key=address_key)
    return (order, stuck)

