"""Parsing formula tokens into an expression tree.

Trees are nested tuples: ("num", float), ("ref", "B3"), ("range", "A1:B2"), ("neg", tree), ("bin", op, left,
right) with op one of + - * / ^, and ("call", NAME, [argument trees]).

Grammar, loosest first: sum := product (("+" | "-") product)*; product := power (("*" | "/") power)*;
power := unary ("^" unary)*; unary := ("-" | "+") unary | primary; primary := num | ref | range | "(" sum ")" |
func [sum ("," sum)*] ")". All binary operators group to the left (so 2^3^2 is (2^3)^2, and 8-2-1 is (8-2)-1);
a unary minus binds tighter than "^", so -2^2 is (-2)^2; a unary "+" is dropped.
"""
from tokens import tokenize
SUM_OPS = '+-'
PRODUCT_OPS = '*/'

def parse_primary(tokens, at):
    """Parse a unary or primary expression starting at tokens[at] (grammar above). Returns a tuple (tree, index of
    the first token after it).

    Valid inputs: tokens is a list as tokens.tokenize returns; at is an index where such an expression starts.
    """
    kind, text = tokens[at]
    if kind == 'op' and text in SUM_OPS:
        inner, nxt = parse_primary(tokens, at + 1)
        return (('neg', inner) if text == '-' else inner, nxt)
    if kind == 'num':
        return (('num', float(text)), at + 1)
    if kind in ('ref', 'range'):
        return ((kind, text), at + 1)
    if kind == '(':
        inner, nxt = parse_sum(tokens, at + 1)
        return (inner, nxt + 1)
    args = []
    nxt = at + 1
    if tokens[nxt][0] != ')':
        arg, nxt = parse_sum(tokens, nxt)
        args.append(arg)
        for _ in range(len(tokens)):
            if tokens[nxt][0] != ',':
                break
            arg, nxt = parse_sum(tokens, nxt + 1)
            args.append(arg)
    return (('call', text, args), nxt + 1)

def parse_level(tokens, at, ops, below):
    """Parse a left-grouping chain of `below` expressions joined by the operators in ops (not tested).

    Returns a tuple (tree, index of the first token after it).
    """
    left, at = below(tokens, at)
    for _ in range(len(tokens)):
        if at >= len(tokens) or tokens[at][0] != 'op' or tokens[at][1] not in ops:
            break
        right, nxt = below(tokens, at + 1)
        left = ('bin', tokens[at][1], left, right)
        at = nxt
    return (left, at)

def parse_power(tokens, at):
    """Parse a power: unary expressions joined by "^", grouped to the left (not tested)."""
    return parse_level(tokens, at, '^', parse_primary)

def parse_product(tokens, at):
    """Parse a product: power expressions joined by "*" and "/", grouped to the left (not tested)."""
    return parse_level(tokens, at, PRODUCT_OPS, parse_power)

def parse_sum(tokens, at):
    """Parse a sum: products joined by "+" and "-", grouped to the left (not tested)."""
    return parse_level(tokens, at, SUM_OPS, parse_product)

def parse_formula(formula):
    """The expression tree of a formula (the text after "="), by the grammar in this module's docstring.

    Numbers become floats; refs and ranges keep their plain text; function names are uppercase. Returns a tree of
    nested tuples as described above.

    Valid inputs: formula is a well-formed formula as tokens.tokenize accepts, with at most 40 tokens.
    """
    tree, _ = parse_sum(tokenize(formula), 0)
    return tree

