"""Turning a typed command into a (verb, noun) pair."""
DIRECTIONS = ['north', 'south', 'east', 'west', 'up', 'down']
SHORT_DIRECTIONS = {'n': 'north', 's': 'south', 'e': 'east', 'w': 'west', 'u': 'up', 'd': 'down'}
ACTION_SYNONYMS = {'get': 'take', 'grab': 'take', 'walk': 'go', 'move': 'go', 'put': 'drop'}
SHORT_VERBS = {'i': 'inventory', 'inv': 'inventory', 'l': 'look'}
VERB_SYNONYMS = {**ACTION_SYNONYMS, **SHORT_VERBS}

def parse_command(text):
    """Normalize a typed command to a (verb, noun) tuple of strings.

    The text is lowercased and split on whitespace.
    - No words: ("none", "").
    - Exactly one word that is a direction in DIRECTIONS, or a short form in SHORT_DIRECTIONS (n s e w u d): ("go",
      the full direction).
    - Otherwise the verb is the first word, replaced by its entry in VERB_SYNONYMS when it has one (get/grab -> take,
      walk/move -> go, put -> drop, i/inv -> inventory, l -> look). The noun is the remaining words joined with one
      space ("" when there are none). If the noun starts with "the " that prefix is removed once. Then, when the verb
      is "go" and the noun is a short direction, the noun is replaced by the full direction.

    Returns a tuple (verb, noun).

    Valid inputs: text is any string of at most 60 characters.
    """
    words = text.lower().split()
    if not words:
        return ('none', '')
    first = SHORT_DIRECTIONS.get(words[0], words[0])
    if len(words) == 1 and first in DIRECTIONS:
        return ('go', first)
    verb = VERB_SYNONYMS.get(words[0], words[0])
    noun = ' '.join(words[1:])
    if noun.startswith('the '):
        noun = noun[4:]
    if verb == 'go':
        noun = SHORT_DIRECTIONS.get(noun, noun)
    return (verb, noun)

