"""Applying commands to the game state, one at a time."""
import copy
from commands import parse_command
from rules import MAX_LOAD, exit_check, load_of, take_check
from world import build_world

def step(world, state, text):
    """Apply one typed command to a state, without changing the given state.

    The command is normalized with commands.parse_command. For ("none", "") the state is returned unchanged with the
    message "". Every other command adds 1 to "turns", whether it succeeds or not, and then:
    - go: rules.exit_check(world, room, noun, carried). On success "room" becomes the target, which is appended to
      "visited" if it is not in it yet.
    - take: rules.take_check(floor of the room, carried, noun). On success one copy of the item leaves the room's
      floor and "carried" becomes the old list plus the item, sorted.
    - drop: if the item is not carried, message "You have no <noun>."; else one copy leaves "carried" and the room's
      floor becomes the old floor plus the item, sorted; message "Dropped: <noun>.".
    - look: message "<room>: exits <directions sorted, joined by ', ' or 'none'>; you see <floor items joined by
      ', ' or 'nothing'>."
    - inventory: message "You carry <carried joined by ', ' or 'nothing'> (load <load_of(carried)>/8)."
    - any other verb: message "I don't understand that."

    Returns a tuple (new state dict, message str).

    Valid inputs: world is a dict as world.build_world returns; state is a dict {"room": a room of world, "carried":
    sorted list of str, "floor": {room: sorted list of str} with an entry for every room of world, "visited": list of
    distinct rooms, "turns": int >= 0}; text is a string as parse_command accepts.
    """
    verb, noun = parse_command(text)
    new = copy.deepcopy(state)
    if verb == 'none':
        return (new, '')
    new['turns'] += 1
    room = new['room']
    floor = new['floor'][room]
    if verb == 'go':
        target, message = exit_check(world, room, noun, new['carried'])
        if target is not None:
            new['room'] = target
            if target not in new['visited']:
                new['visited'].append(target)
        return (new, message)
    if verb == 'take':
        ok, message = take_check(floor, new['carried'], noun)
        if ok:
            floor.remove(noun)
            new['carried'] = sorted(new['carried'] + [noun])
        return (new, message)
    if verb == 'drop':
        if noun not in new['carried']:
            return (new, f'You have no {noun}.')
        new['carried'].remove(noun)
        new['floor'][room] = sorted(floor + [noun])
        return (new, f'Dropped: {noun}.')
    if verb == 'look':
        exits = ', '.join(sorted(world[room]['exits'])) or 'none'
        stuff = ', '.join(floor) or 'nothing'
        return (new, f'{room}: exits {exits}; you see {stuff}.')
    if verb == 'inventory':
        carried = ', '.join(new['carried']) or 'nothing'
        return (new, f"You carry {carried} (load {load_of(new['carried'])}/{MAX_LOAD}).")
    return (new, "I don't understand that.")

def run_script(world_lines, start, commands):
    """Play a whole script of commands from the start room.

    The world is world.build_world(world_lines). The first state is {"room": start, "carried": [], "floor": {each
    room: a copy of its items}, "visited": [start], "turns": 0}. Each command is applied in order with step.

    Returns a dict {"final": the final state, a dict with the keys "room", "carried", "floor", "visited" and
    "turns" as step uses them, "messages": the list of the messages of all commands whose message is not "" (empty
    commands give no message), in order}.

    Valid inputs: world_lines is a list as build_world accepts that defines the room start; commands is a list of 0 to
    40 strings as parse_command accepts.
    """
    world = build_world(world_lines)
    floor = {room: list(world[room]['items']) for room in world}
    state = {'room': start, 'carried': [], 'floor': floor, 'visited': [start], 'turns': 0}
    messages = []
    for text in commands:
        state, message = step(world, state, text)
        if message:
            messages.append(message)
    return {'final': state, 'messages': messages}

