"""Rules for moving through exits and carrying items."""
ITEM_WEIGHTS = {'anvil': 6, 'shield': 4, 'sword': 3, 'lamp': 2, 'rope': 2, 'book': 2, 'crown': 2}
MAX_LOAD = 8

def load_of(items):
    """The total weight of a list of items.

    Each item weighs its value in ITEM_WEIGHTS (anvil 6, shield 4, sword 3, lamp 2, rope 2, book 2, crown 2); any
    other item weighs 1. Duplicates count once per copy.

    Returns an int (0 for an empty list).

    Valid inputs: items is a list of 0 to 20 strings.
    """
    total = 0
    for item in items:
        total += ITEM_WEIGHTS.get(item, 1)
    return total

def exit_check(world, room, direction, carried):
    """Can the player in `room` go `direction`?

    - The room has no exit in that direction: (None, "You can't go that way.").
    - The exit needs a key (its key is not None) and the key is not in carried: (None, "The way <direction> is
      locked.").
    - Otherwise: (target room, "You go <direction> to <target room>.").

    Returns a tuple (target room or None, message str).

    Valid inputs: world is a dict as world.build_world returns; room is one of its rooms; direction is any string;
    carried is a list of strings.
    """
    exits = world[room]['exits']
    if direction not in exits:
        return (None, "You can't go that way.")
    target, key = exits[direction]
    if key is not None and key not in carried:
        return (None, f'The way {direction} is locked.')
    return (target, f'You go {direction} to {target}.')

def take_check(floor_items, carried, item):
    """Can the player pick up `item` from a room whose floor holds floor_items?

    - item is not in floor_items: (False, "There is no <item> here.").
    - load_of(carried) plus the item's weight is more than MAX_LOAD (8): (False, "The <item> is too heavy.").
      A total of exactly 8 is allowed.
    - Otherwise: (True, "Taken: <item>.").

    Returns a tuple (bool, message str).

    Valid inputs: floor_items and carried are lists of 0 to 20 strings; item is a string.
    """
    if item not in floor_items:
        return (False, f'There is no {item} here.')
    weight = ITEM_WEIGHTS.get(item, 1)
    if load_of(carried) + weight > MAX_LOAD:
        return (False, f'The {item} is too heavy.')
    return (True, f'Taken: {item}.')

