"""Reading tank descriptions. All volumes are whole litres."""
DEFAULTS = {'cap': 1000, 'level': 0, 'low': 0, 'high': 1000, 'pump': 0, 'share': 0}

def parse_tank(line):
    """Parse a tank line "NAME key=value key=value ...".

    Words are separated by runs of spaces; the first word is the name. Keys cap, level, low, high, pump (pump
    rate in litres per hour) and share (weight in the demand split) take int values; key "to" names the tank that
    receives this tank's overflow. Missing keys take DEFAULTS (cap 1000, level 0, low 0, high 1000, pump 0,
    share 0) and "to" defaults to None. Finally level is limited to at most cap.

    Returns a dict {"name": str, "cap", "level", "low", "high", "pump", "share": int, "to": str or None}.

    Valid inputs: line is a name followed by key=value words with the keys above (values ints >= 0, except "to");
    a key may appear once at most.
    """
    words = line.split()
    tank = {'name': words[0], 'to': None}
    tank.update(DEFAULTS)
    for word in words[1:]:
        key, value = word.split('=')
        if key == 'to':
            tank['to'] = value
        else:
            tank[key] = int(value)
    if tank['level'] > tank['cap']:
        tank['level'] = tank['cap']
    return tank

